/** Normative Polish text of criteria in WCAG 2.1, as sanitized HTML, keyed by criterion number. */
export const criterionTexts: Readonly<Record<string, string>> = {
  "1.1.1": "<p>Wszelkie treści nietekstowe przedstawione użytkownikowi mają swoją tekstową alternatywę, która służy tym samym celom, z wyjątkiem sytuacji opisanych poniżej:</p><dl><dt>Kontrolki i wprowadzanie danych przez użytkownika</dt><dd><p>Jeśli treść nietekstowa jest kontrolką użytkownika lub polem wprowadzania danych, posiada wtedy nazwę opisującą jej przeznaczenie. (Kryterium sukcesu 4.1.2 podaje dodatkowe wymagania dotyczące kontrolek oraz wprowadzania danych przez użytkownika.)</p></dd><dt>Multimedia</dt><dd><p>Jeśli treścią nietekstową są media oparte na czasie, wtedy alternatywa tekstowa zawiera przynajmniej opisowe określenie treści nietekstowej. (Wytyczna 1.2 podaje dodatkowe wymagania, jeśli chodzi o media.)</p></dd><dt>Test</dt><dd><p>Jeśli treść nietekstowa jest testem lub ćwiczeniem, które utraciłoby swój sens ze względu na przedstawienie tej samej treści w postaci tekstu, wtedy alternatywa w postaci tekstu podawać powinna przynajmniej opis pozwalający zrozumieć przeznaczenie treści nietekstowej.</p></dd><dt>Odczucie zmysłowe</dt><dd><p>Jeśli treść nietekstowa ma za zadanie przede wszystkim tworzyć konkretne odczucie zmysłowe, wtedy alternatywa w postaci tekstu jest opisem pozwalającym zrozumieć przeznaczenie treści nietekstowej.</p></dd><dt>CAPTCHA</dt><dd><p>Jeśli celem treści nietekstowej jest potwierdzenie, że do treści ma dostęp człowiek, a nie komputer, wtedy dostarcza się alternatywę w postaci tekstu, która identyfikuje oraz opisuje cel treści nietekstowej. Dostarcza się również alternatywnych zabezpieczeń typu CAPTCHA, dostosowanych do różnych możliwości percepcji użytkowników, uwzględniając różne rodzaje niepełnosprawności.</p></dd><dt>Cele dekoracyjne, formatowanie, treść niewidoczna</dt><dd><p>Jeśli treść nietekstowa pełni funkcję czysto dekoracyjną, używana jest do formatowania wizualnego lub też nie jest przedstawiana użytkownikowi, powinna być wdrożona w sposób umożliwiający technologiom wspomagającym jej zignorowanie.</p></dd></dl>",
  "1.2.1": "<p>Dla mediów nagranych w systemie tylko audio lub tylko wideo stosuje się następujące zasady, z wyjątkiem sytuacji, kiedy nagranie audio lub wideo jest alternatywą dla tekstu i w taki sposób jest oznaczone:</p><dl><dt>Alternatywa dla audio</dt><dd><p>Zapewniona jest alternatywa tekstowa dla nagrań dźwiękowych przedstawiająca tę samą treść, co nagranie audio.</p></dd><dt>Alternatywa dla wideo</dt><dd><p>Zapewniona jest alternatywa tekstowa albo audiodeskrypcja dla nagrań zawierających tylko wideo przedstawiająca tę samą treść, co nagranie wideo.</p></dd></dl>",
  "1.2.2": "<p>Do wszystkich nagrań audio w multimediach zsynchronizowanych (dźwięk i obraz), z wyjątkiem sytuacji, kiedy są one alternatywami dla tekstu i w taki sposób są oznaczone, zapewnione są napisy rozszerzone.</p>",
  "1.2.3": "<p>Zapewniona jest alternatywa dla multimediów lub audiodeskrypcja dla nagrań wideo w multimediach zsynchronizowanych (dźwięk i obraz), z wyjątkiem sytuacji, kiedy są one alternatywami dla tekstu i w taki sposób są oznaczone.</p>",
  "1.2.4": "<p>Do wszystkich treści audio w multimediach zsynchronizowanych (dźwięk i obraz) przekazywanych na żywo zapewnione są napisy rozszerzone.</p>",
  "1.2.5": "<p>Zapewniona jest audiodeskrypcja dla wszystkich nagrań wideo w multimediach zsynchronizowanych.</p>",
  "1.2.6": "<p>Zapewnione jest tłumaczenie w języku migowym wszystkich nagrań audio w multimediach zsynchronizowanych (dźwięk i obraz).</p>",
  "1.2.7": "<p>Jeśli przerwy w ścieżce dźwiękowej nagrania nie pozwalają na zamieszczenie audiodeskrypcji przekazującej sens treści w wystarczającym stopniu, dla wszystkich nagrań wideo w multimediach zsynchronizowanych (dźwięk i obraz) zapewniona jest rozszerzona audiodeskrypcja.</p>",
  "1.2.8": "<p>Zapewniona jest alternatywa dla wszystkich nagrań w multimediach zsynchronizowanych (dźwięk i obraz) oraz dla wszystkich nagrań tylko wideo (sam obraz).</p>",
  "1.2.9": "<p>Zapewniona jest alternatywa dla multimediów przedstawiająca informacje takie same, jak w przekazie tylko audio na żywo.</p>",
  "1.3.1": "<p>Informacje, struktura oraz relacje między treściami przekazywane poprzez prezentację mogą być odczytane przez program komputerowy lub istnieją w postaci tekstu.</p>",
  "1.3.2": "<p>Jeśli kolejność, w jakiej przedstawiona jest treść, ma znaczenie dla zrozumienia treści — prawidłowa kolejność odczytu musi być określona programowo.</p>",
  "1.3.3": "<p>Instrukcje co do zrozumienia i operowania treścią nie opierają się wyłącznie na właściwościach zmysłowych, takich jak: kształt, rozmiar, wzrokowa lokalizacja, orientacja w przestrzeni lub dźwięk.</p><blockquote><p><strong>Uwaga</strong></p><p>Uwaga: Wymagania dotyczące koloru można znaleźć w Wytycznej 1.4.</p></blockquote>",
  "1.3.4": "<p>Treść nie ogranicza swojego widoku i działania do jednej orientacji wyświetlania, takiej jak pionowa lub pozioma, chyba że określona orientacja wyświetlania jest istotna.</p><blockquote><p><strong>Uwaga</strong></p><p>Przykłady, w których szczególna orientacja wyświetlacza może mieć zasadnicze znaczenie, to np. czek bankowy, aplikacja na pianino, slajdy do projektora czy telewizora lub treść rzeczywistości wirtualnej, gdy treść nie musi być ograniczona do orientacji poziomej lub pionowej.</p></blockquote>",
  "1.3.5": "<p>Cel każdego pola zbierającego informacje o użytkowniku może być programowo określony, gdy:</p><ul><li>Pole zbierające dane służy celowi określonemu w sekcji Przeznaczenie pól danych w komponentach interfejsu użytkownika; oraz</li><li>Treść jest implementowana za pomocą technologii obsługującej określanie w polach formularza typu oczekiwanych danych.</li></ul>",
  "1.3.6": "<p>W treściach zaimplementowanych przy użyciu języków znaczników przeznaczenie komponentów interfejsu użytkownika, ikon i obszarów kluczowych może zostać określone programowo.</p>",
  "1.4.1": "<p>Kolor nie jest wykorzystywany jako jedyny wizualny sposób przekazywania informacji, wskazywania czynności do wykonania lub oczekiwania na odpowiedź, czy też wyróżniania elementów wizualnych.</p><blockquote><p><strong>Uwaga</strong></p><p>To kryterium sukcesu dotyczy szczególnie percepcji koloru. Inne formy percepcji zostały omówione w Wytycznej 1.3, w tym programowy dostęp do koloru oraz inne rodzaje zaprogramowania prezentacji wizualnej.</p></blockquote>",
  "1.4.2": "<p>Jeśli jakieś nagranie audio włącza się automatycznie na danej stronie i jest odtwarzane przez okres dłuższy niż 3 sekundy, istnieje mechanizm umożliwiający przerwanie lub wyłączenie nagrania albo mechanizm kontrolujący poziom głośności niezależnie od poziomu głośności całego systemu.</p><blockquote><p><strong>Uwaga</strong></p><p>Ponieważ każda treść, która nie spełnia tego kryterium sukcesu, może utrudnić użytkownikowi odczytanie całej strony, wszelkie treści na stronie (bez względu na to, czy spełniają inne kryteria sukcesu, czy nie) muszą spełnić niniejsze kryterium. Więcej informacji: 5 Spełnienie wymagań: Bez zakłóceń.</p></blockquote>",
  "1.4.3": "<p>Wizualna prezentacja tekstu lub obrazu tekstu posiada współczynnik kontrastu wynoszący przynajmniej 4.5:1, poza następującymi wyjątkami:</p><dl><dt>Duży tekst</dt><dd><p>Duży tekst oraz grafiki takiego tekstu posiadają kontrast przynajmniej 3:1;</p></dd><dt>Incydentalne</dt><dd><p>Tekst lub obrazy tekstu, które są częścią nieaktywnego komponentu interfejsu użytkownika, które są czystą dekoracją, które nie są widoczne lub które są częścią obrazu zawierającego inne istotne treści wizualne, nie wymagają minimalnego kontrastu;</p></dd><dt>Logotyp</dt><dd><p>Tekst, który jest częścią logo lub nazwy własnej produktu (marki), nie wymaga minimalnego kontrastu.</p></dd></dl>",
  "1.4.4": "<p>Oprócz napisów rozszerzonych oraz obrazów tekstu, rozmiar tekstu może zostać powiększony do 200% bez użycia technologii wspomagających oraz bez utraty treści lub funkcjonalności.</p>",
  "1.4.5": "<p>Jeśli wykorzystywane technologie mogą przedstawiać treść wizualnie, do przekazywania informacji wykorzystuje się tekst, a nie obraz tekstu, z wyjątkiem następujących sytuacji:</p><dl><dt>Możliwy do dostosowania</dt><dd><p>Obraz tekstu może być dostosowany wizualnie do wymagań użytkownika;</p></dd><dt>Istotny</dt><dd><p>Prezentacja tekstu w postaci graficznej jest istotna dla zrozumienia przekazywanej informacji.</p></dd></dl><blockquote><p><strong>Uwaga</strong></p><p>Logotyp (tekst będący częścią logo lub nazwy własnej produktu) jest uznawany za istotny.</p></blockquote>",
  "1.4.6": "<p>Wizualna prezentacja tekstu lub obrazu tekstu posiada współczynnik kontrastu wynoszący przynajmniej 7:1, poza następującymi wyjątkami:</p><dl><dt>Duży tekst</dt><dd><p>Duży tekst oraz grafiki takiego tekstu posiadają kontrast przynajmniej 4,5:1;</p></dd><dt>Incydentalne</dt><dd><p>Tekst lub obrazy tekstu, które są częścią nieaktywnego komponentu interfejsu użytkownika, które są czystą dekoracją, które nie są widoczne lub które są częścią obrazu zawierającego inne istotne treści wizualne, nie wymagają wzmocnionego kontrastu;</p></dd><dt>Logotyp</dt><dd><p>Tekst, który jest częścią logo lub nazwy własnej produktu (marki), nie wymaga wzmocnionego kontrastu.</p></dd></dl>",
  "1.4.7": "<p>Dla nagranej treści tylko audio, która (1) na pierwszym planie zawiera głównie mowę, (2) nie jest dźwiękową CAPTCHA lub logo w postaci dźwiękowej, oraz (3) nie jest wokalizacją mającą na celu głównie ekspresję muzyczną, np. w przypadku śpiewu lub rapu, przynajmniej jedno z poniższych założeń jest spełnione:</p><dl><dt>Bez treści w tle</dt><dd><p>Nagranie audio nie zawiera dźwięków tła.</p></dd><dt>Możliwość wyłączenia</dt><dd><p>Dźwięki tła mogą zostać wyłączone.</p></dd><dt>20 dB</dt><dd><p>Głośność dźwięków tła jest przynajmniej o 20 decybeli mniejsza, niż głośność mowy, która stanowi główną treść nagrania, z wyjątkiem okazyjnych, jedno– lub dwusekundowych dźwięków tła.</p><blockquote><p><strong>Uwaga</strong></p><p>Z definicji terminu „decybel” wynika, iż dźwięki tła spełniające powyższy wymóg będą 4 razy cichsze od głównej treści nagrania.</p></blockquote></dd></dl>",
  "1.4.8": "<p>Dla wizualnego przedstawienia bloków tekstu, istnieje mechanizm, za pomocą którego można osiągnąć, co następuje:</p><ul><li>Kolory na pierwszym planie oraz kolory tła mogą być zmienione przez użytkownika.</li><li>Szerokość nie przekracza 80 znaków (40 w przypadku alfabetów: chińskiego, japońskiego i koreańskiego).</li><li>Tekst nie jest wyjustowany (tzn. wyrównany do prawego i lewego marginesu).</li><li>Odstępy między wierszami w akapitach wynoszą przynajmniej 1,5 wysokości linii, a odległość między akapitami jest przynajmniej 1,5 razy większa niż ta pomiędzy wierszami.</li><li>Rozmiar tekstu może zostać powiększony do 200% bez użycia technologii wspomagających, nie wymagając od użytkownika, chcącego odczytać cały wiersz, przesuwania tekstu w poziomie przy zmaksymalizowanym oknie ekranu.</li></ul>",
  "1.4.9": "<p>Obrazy tekstu są wykorzystywane jedynie w celach czysto dekoracyjnych lub też w przypadkach, gdy taka prezentacja tekstu jest istotna dla przekazywanej informacji.</p><blockquote><p><strong>Uwaga</strong></p><p>Logotyp (tekst będący częścią logo lub nazwy własnej produktu) jest uznawany za istotny.</p></blockquote>",
  "1.4.10": "<p>Treść może być prezentowana bez utraty informacji lub funkcjonalności, bez konieczności przewijania w dwóch wymiarach dla:</p><ul><li>Pionowego przewijania treści o szerokości odpowiadającej 320 pikselom CSS;</li><li>Poziomego przewijania treści na wysokości odpowiadającej 256 pikselom CSS.</li></ul><p>Wyjątkiem są te części treści, które wymagają dwuwymiarowego układu ze względu na sposób używania lub znaczenie.</p><blockquote><p><strong>Uwaga</strong></p><p>320 pikseli CSS odpowiada początkowej szerokości obszaru roboczego 1280 pikseli CSS przy 400% powiększeniu. Dla treści internetowych, które są przeznaczone do przewijania w poziomie (np. z tekstem pionowym), 256 pikseli CSS odpowiada początkowej wysokości obszaru roboczego 1024 pikseli CSS z 400% powiększeniem.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Przykładami treści, które wymagają dwuwymiarowego układu są obrazy prezentujące np. mapy i diagramy, wideo, gry, prezentacje, tabele danych (nie poszczególne komórki) oraz interfejsy, w których konieczne jest zachowanie pasków narzędzi w widoku podczas manipulacji treścią. Dopuszczalne jest zapewnienie przewijania dwuwymiarowego dla takich części treści.</p></blockquote>",
  "1.4.11": "<p>Wizualna prezentacja następujących elementów ma współczynnik kontrastu co najmniej 3:1 względem sąsiednich kolorów:</p><dl><dt>Komponenty interfejsu użytkownika</dt><dd>Informacje wizualne wymagane do identyfikacji komponentów interfejsu użytkownika i ich stanów, z wyjątkiem nieaktywnych składników lub gdy wygląd komponentu jest określony przez agenta użytkownika i nie jest modyfikowany przez autora;</dd><dt>Obiekty graficzne</dt><dd>Części grafiki wymagane do zrozumienia treści, z wyjątkiem sytuacji, gdy konkretna prezentacja grafiki ma istotne znaczenie dla przekazywanych informacji.</dd></dl>",
  "1.4.12": "<p>W treściach tworzonych za pomocą języków znaczników, umożliwiających ustawienie poniższych właściwości stylu, nie następuje utrata żadnych treści lub funkcjonalności, gdy tekst ustawiony zostanie tak, aby uwzględniał wszystkie poniższe parametry oraz gdy wprowadzone zostaną zmiany w jakiejkolwiek innej właściwości stylu:</p><ul><li>Wysokość linii (odstęp między wierszami) do co najmniej 1,5-krotności rozmiaru czcionki;</li><li>Odstęp między akapitami co najmniej 2 razy większy od rozmiaru czcionki;</li><li>Odstępy między literami (tracking) do co najmniej 0,12-krotności rozmiaru czcionki;</li><li>Odstępy między wyrazami do co najmniej 0,16 wielkości czcionki.</li></ul><p>Wyjątek: Języki naturalne i skrypty, które nie wykorzystują jednej lub więcej z tych właściwości stylu tekstowego w tekście pisanym, mogą być zgodne przy użyciu tylko tych właściwości, które istnieją dla tej kombinacji języka i skryptu.</p>",
  "1.4.13": "<p>Gdy jakaś treść staje się widoczna po otrzymaniu kursora lub fokusu klawiatury, a po ich usunięciu znika, spełnione są poniższe warunki:</p><dl><dt>Odrzucone</dt><dd>Istnieje mechanizm umożliwiający odrzucenie dodatkowej treści bez przesuwania wskaźnika myszy lub fokusu klawiatury, chyba że dodatkowa treść przekazuje błąd wprowadzanych danych lub nie przesłania ani nie zastępuje innej treści;</dd><dt>Wskazywane</dt><dd>Jeśli wskaźnik myszy (hover) może wyzwolić dodatkową treść, wówczas wskaźnik może zostać przeniesiony na dodatkową treść bez znikania dodatkowej treści;</dd><dt>Trwałe</dt><dd>Dodatkowa treść pozostaje widoczna do momentu usunięcia wyzwalacza aktywacji lub fokusu, użytkownik odrzuca go lub jego informacje nie są już ważne.</dd></dl><p>Wyjątek: Wizualna prezentacja dodatkowej treści jest kontrolowana przez program użytkownika i nie jest modyfikowana przez autora.</p><blockquote><p><strong>Uwaga</strong></p><p>Przykłady dodatkowej treści kontrolowanej przez program użytkownika obejmują podpowiedzi przeglądarki utworzone przy użyciu atrybutu HTML <code>title</code>.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Niestandardowe podpowiedzi, podmenu i inne niemodalne wyskakujące okienka wyświetlane w dymku i fokusie to przykłady dodatkowej treści objętej tym kryterium.</p></blockquote>",
  "2.1.1": "<p>Wszystkie funkcjonalności w treści są obsługiwane za pomocą interfejsu klawiatury, bez wymogu określonego czasu użycia poszczególnych klawiszy, z wyjątkiem sytuacji, kiedy dana funkcja wymaga wprowadzenia informacji przez użytkownika w oparciu o ścieżkę ruchów, a nie w oparciu o punkty końcowe wejścia.</p><blockquote><p><strong>Uwaga</strong></p><p>Ten wyjątek dotyczy danej funkcji, a nie techniki wprowadzania danych. Na przykład, jeśli do wprowadzania tekstu używa się pisma odręcznego, technika wprowadzania (pismo odręczne) wymaga wprowadzenia informacji w oparciu o ścieżkę, jednak powiązana z tym funkcja (wprowadzenie tekstu) już tego nie wymaga.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>To nie powinno blokować ani ograniczać użycia interfejsu innymi metodami niż klawiatura, np. za pomocą myszki.</p></blockquote>",
  "2.1.2": "<p>Jeśli fokus klawiatury można przemieścić do danego komponentu treści za pomocą interfejsu klawiatury, to może on być z niego usunięty również za pomocą interfejsu klawiatury, a jeśli wymagane jest użycie czegoś więcej niż tylko strzałek, tabulatora lub innych standardowych metod wyjścia, użytkownik musi otrzymać odpowiednią podpowiedź, w jaki sposób usunąć fokus z danego komponentu.</p><blockquote><p><strong>Uwaga</strong></p><p>Ponieważ każda treść, która nie spełnia tego kryterium sukcesu może utrudnić użytkownikowi skorzystanie z całej strony, cała treść danej strony (bez względu na to, czy spełnia inne kryteria, czy nie) musi spełnić powyższe kryterium. Więcej informacji: Spełnienie wymagań 5: Bez zakłóceń.</p></blockquote>",
  "2.1.3": "<p>Wszystkie funkcjonalności w treści są obsługiwane za pomocą interfejsu klawiatury, bez wymogu określonego czasu użycia poszczególnych klawiszy.</p>",
  "2.1.4": "<p>Jeśli skrót klawiaturowy jest zaimplementowany w treści tylko przy użyciu jednego znaku (litery, w tym wielkiej i małej, cyfry lub symbolu), to przynajmniej jedno z poniższych jest prawdziwe:</p><dl><dt>Wyłączanie</dt><dd>Istnieje mechanizm wyłączania skrótu;</dd><dt>Mapowanie</dt><dd>Istnieje mechanizm zmiany mapowania skrótu w celu użycia jednego lub więcej niedrukowalnych znaków klawiatury (np. Ctrl, Alt, itp.);</dd><dt>Aktywny tylko po otrzymaniu fokusu</dt><dd>Skrót klawiaturowy dla komponentu interfejsu użytkownika jest aktywny tylko wtedy, gdy ten komponent ma fokus.</dd></dl>",
  "2.2.1": "<p>Gdy czas korzystania z treści jest ograniczany, spełniony jest przynajmniej jeden z poniższych warunków:</p><dl><dt>Wyłączenie</dt><dd><p>Użytkownik może wyłączyć limit czasowy, zanim czas upłynie; lub</p></dd><dt>Dostosowanie</dt><dd><p>Użytkownik może swobodnie dostosować limit czasowy (przynajmniej o wartość 10 razy większą od wartości domyślnej), zanim czas upłynie; lub</p></dd><dt>Wydłużenie</dt><dd><p>Użytkownik jest ostrzegany przed upłynięciem limitu czasowego i ma przynajmniej 20 sekund na wydłużenie limitu za pomocą prostej czynności (np. „wciśnij klawisz spacji”) oraz może wydłużyć limit przynajmniej dziesięciokrotnie; lub</p></dd><dt>Wyjątek dotyczący czasu rzeczywistego</dt><dd><p>Limit czasowy jest wymaganym komponentem jakiejś czynności w czasie rzeczywistym (np. aukcji) i nie ma możliwości zmiany limitu; lub</p></dd><dt>Wyjątek dotyczący istoty czynności</dt><dd><p>Limit czasowy jest istotny i wydłużenie go anulowałoby lub zaburzałoby daną czynność; lub</p></dd><dt>Wyjątek 20 godzin</dt><dd><p>Limit czasowy przekracza 20 godzin.</p></dd></dl><blockquote><p><strong>Uwaga</strong></p><p>To kryterium sukcesu ma na celu zapewnienie użytkownikowi wystarczającego czasu na wykonanie czynności, bez niespodziewanych zmian treści lub kontekstu, które mogą być wynikiem limitu czasowego. Powinien on być rozpatrywany w połączeniu z kryterium sukcesu 3.2.1, które nakłada ograniczenia na zmiany treści lub kontekstu w wyniku działania użytkownika.</p></blockquote>",
  "2.2.2": "<p>Gdy treść się porusza, migocze, przesuwa lub jest automatycznie aktualizowana, spełnione są wszystkie poniższe warunki:</p><dl><dt>Poruszanie się, przesuwanie, migotanie</dt><dd><p>Każdą informację, która porusza się, przesuwa lub miga, a takie działanie (1) włącza się automatycznie, (2) jest widoczne dłużej niż 5 sekund, (3) jest przedstawiane równolegle z inną treścią — użytkownik może wstrzymać, zatrzymać lub ukryć za pomocą dostępnego mechanizmu, chyba że poruszanie się, przesuwanie lub migotanie jest częścią czynności, w której takie działanie jest istotne, oraz:</p></dd><dt>Automatyczna aktualizacja</dt><dd><p>Każdą automatycznie aktualizującą się informację, która (1) włącza się automatycznie oraz (2) jest przedstawiana równolegle z inną treścią — użytkownik może wstrzymać, zatrzymać lub kontrolować częstotliwość aktualizacji za pomocą dostępnego mechanizmu, chyba, że automatyczna aktualizacja jest częścią takiej czynności, w której takie działanie jest niezbędne.</p></dd></dl><blockquote><p><strong>Uwaga</strong></p><p>Wytyczna 2.3 zawiera więcej informacji na temat treści migoczącej lub zawierającej błyski.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Ponieważ każda treść, która nie spełnia tego kryterium sukcesu może utrudnić użytkownikowi skorzystanie z całej strony, cała zawartość danej strony (bez względu na to, czy spełnia inne kryteria, czy nie) musi spełnić powyższe kryterium. Więcej informacji: Spełnienie wymagań: Bez zakłóceń.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Treść, która jest aktualizowana okresowo przez aplikację lub przesyłana w sposób ciągły do programu użytkownika, nie musi być przechowywana lub przedstawiana w czasie pomiędzy wstrzymaniem a wznowieniem prezentacji, ponieważ może to być technicznie niemożliwe, a w wielu przypadkach mogłoby wprowadzać użytkownika w błąd.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Animacja, która pojawia się w czasie poprzedzającym załadowanie treści, może być uznana za istotną, jeśli wszyscy użytkownicy nie mogą dokonać interakcji w tym czasie oraz jeśli brak wskazania etapu załadowania mógłby wprowadzić użytkownika w błąd lub mogłoby mu się wydawać, że załadowanie treści zostało zawieszone albo przerwane.</p></blockquote>",
  "2.2.3": "<p>Ograniczenie czasowe nie jest istotną częścią czynności prezentowanej na stronie, chyba, że są to nieinteraktywne multimedia zsynchronizowane lub wydarzenia w czasie rzeczywistym.</p>",
  "2.2.4": "<p>Przerywanie pracy może być odłożone w czasie lub odrzucone przez użytkownika, chyba że jest to sytuacja wyjątkowa.</p>",
  "2.2.5": "<p>Kiedy kończy się czas sesji autoryzowanej przez użytkownika, może on kontynuować czynność bez utraty danych po ponownej autoryzacji.</p>",
  "2.2.6": "<p>Użytkownicy muszą być ostrzeżeni o limicie czasu bezczynności użytkownika, którego przekroczenie mogłoby spowodować utratę danych, chyba że dane te są przechowywane przez ponad 20 godzin, gdy uczestnik nie podejmie żadnych działań.</p><blockquote><p><strong>Uwaga</strong></p><p>Przepisy dotyczące prywatności mogą wymagać wyraźnej zgody użytkownika przed uwierzytelnieniem tożsamości użytkownika i zachowaniem danych użytkownika. W przypadkach, gdy użytkownik jest nieletni, wyraźna zgoda może nie być wymagana w większości jurysdykcji, krajów lub regionów. Przy rozważaniu ochrony danych jako podejścia do spełnienia tego kryterium sukcesu zaleca się konsultacje ze specjalistami ds. prywatności i radcą prawnym.</p></blockquote>",
  "2.3.1": "<p>Strony internetowe nie zawierają w swojej treści niczego, co błyska częściej niż trzy razy w ciągu jednej sekundy, lub też błysk nie przekracza wartości granicznych dla błysków ogólnych i czerwonych.</p><blockquote><p><strong>Uwaga</strong></p><p>Ponieważ każda treść, która nie spełnia tego kryterium sukcesu może utrudnić użytkownikowi skorzystanie z całej strony, cała treść danej strony (bez względu na to, czy spełnia inne kryteria, czy nie) musi spełnić powyższe kryterium. Więcej informacji: Spełnienie wymagań: Bez zakłóceń.</p></blockquote>",
  "2.3.2": "<p>Strony internetowe nie zawierają w swojej treści niczego, co błyska częściej niż trzy razy w ciągu jednej sekundy.</p>",
  "2.3.3": "<p>Animacja ruchowa wyzwalana przez interakcję może być wyłączona, chyba że animacja jest istotna dla funkcjonalności lub przekazywanych informacji.</p>",
  "2.4.1": "<p>Istnieje mechanizm, który umożliwia pominięcie bloków treści powtarzanych na wielu stronach internetowych.</p>",
  "2.4.2": "<p>Strony internetowe mają tytuły, które opisują ich cel lub przedstawiają ich temat.</p>",
  "2.4.3": "<p>Jeśli strona internetowa może być nawigowana sekwencyjnie, a kolejność nawigacji wpływa na zrozumienie lub funkcjonalność strony, komponenty przyjmują fokus w kolejności, dzięki której zachowany jest sens i funkcjonalność treści.</p>",
  "2.4.4": "<p>Cel każdego łącza może wynikać z samej treści łącza lub z treści tekstu powiązanego z kontekstem łącza określonym programowo, poza tymi przypadkami, kiedy cel łącza i tak byłby niejasny dla użytkowników.</p>",
  "2.4.5": "<p>Istnieje więcej niż jeden sposób umożliwiający zlokalizowanie strony internetowej w zestawie stron internetowych, z wyjątkiem sytuacji, kiedy dana strona jest wynikiem jakiejś procedury lub jednym z jej etapów.</p>",
  "2.4.6": "<p>Nagłówki i etykiety opisują temat lub cel treści.</p>",
  "2.4.7": "<p>Każdy interfejs posiadający możliwość obsługi przy pomocy klawiatury ma tryb obsługi, w którym fokus klawiatury jest stale widoczny.</p>",
  "2.4.8": "<p>Zapewniona jest informacja, w którym miejscu w zestawie stron internetowych znajduje się użytkownik.</p>",
  "2.4.9": "<p>Istnieje mechanizm umożliwiający zidentyfikowanie celu każdego łącza z samej jego treści, poza tymi przypadkami, kiedy cel łącza i tak byłby niejasny dla użytkowników.</p>",
  "2.4.10": "<p>Nagłówki sekcji są używane do porządkowania treści.</p><blockquote><p><strong>Uwaga</strong></p><p>Termin „nagłówek” został tu użyty w swoim ogólnym znaczeniu, obejmując tytuły i inne sposoby przypisywania nagłówków do różnego rodzaju treści.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Powyższe kryterium sukcesu dotyczy sekcji samych tekstów, a nie komponentów interfejsu użytkownika, które omawiane są osobno w ramach kryterium sukcesu 4.1.2.</p></blockquote>",
  "2.5.1": "<p>Wszystkie funkcjonalności wykorzystujące do obsługi gesty wielopunktowe lub oparte na ścieżkach mogą być obsługiwane za pomocą dotyku jednopunktowego bez gestu opartego na ścieżce, chyba że istotny jest gest wielopunktowy lub oparty na ścieżce.</p><blockquote><p><strong>Uwaga</strong></p><p>Ten wymóg dotyczy treści internetowych, które interpretują działania dotykowe (tj. nie dotyczy to działań wymaganych do obsługi programu użytkownika (przeglądarki internetowej) lub technologii wspomagającej).</p></blockquote>",
  "2.5.2": "<p>W przypadku funkcjonalności, które są wywoływane za pomocą dotyku jednopunktowego, co najmniej jedno z poniższych twierdzeń jest prawdziwe:</p><dl><dt>Brak zdarzenia</dt><dd>Naciskanie nie wywołuje jakiejkolwiek części zdarzenia;</dd><dt>Przerwanie lub cofnięcie</dt><dd>Zdarzenie jest zależne od zwolnienia nacisku i istnieje mechanizm, którym można je przerwać lub cofnąć po zwolnieniu nacisku;</dd><dt>Odwrócenie zdarzenia</dt><dd>Zwolnienie nacisku cofa wywołane zdarzenie i przywraca stan sprzed zdarzenia;</dd><dt>Istotne</dt><dd>Wciśnięcie jest niezbędne do wywołania zdarzenia.</dd></dl><blockquote><p><strong>Uwaga</strong></p><p>Funkcje emulujące naciśnięcie klawiszy klawiatury lub klawiatury numerycznej są uważane za niezbędne.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Ten wymóg dotyczy treści internetowych, które interpretują działania dotykowe (tj. nie dotyczy to działań wymaganych do obsługi programu użytkownika lub technologii wspomagającej).</p></blockquote>",
  "2.5.3": "<p>W przypadku komponentów interfejsu użytkownika z etykietami zawierającymi tekst lub obrazy tekstu, nazwa zawiera tekst, który jest prezentowany wizualnie.</p><blockquote><p><strong>Uwaga</strong></p><p>Najlepszą praktyką jest umieszczenie tekstu etykiety na początku nazwy.</p></blockquote>",
  "2.5.4": "<p>Funkcjonalność, którą można obsługiwać za pomocą ruchu urządzenia lub ruchu użytkownika, można również obsługiwać za pomocą komponentów interfejsu użytkownika, a reagowanie na ruch można wyłączyć, aby zapobiec przypadkowemu uruchomieniu, z wyjątkiem sytuacji, gdy:</p><dl><dt>Obsługiwany interfejs</dt><dd>Ruch służy do obsługi funkcjonalności poprzez interfejs obsługiwany przez dostępność;</dd><dt>Istotny</dt><dd>Ruch jest niezbędny dla funkcji, a to spowodowałoby unieważnienie działania.</dd></dl>",
  "2.5.5": "<p>Rozmiar celu punktu dotykowego wynosi co najmniej 44 na 44 piksele CSS, chyba że:</p><dl><dt>Odpowiednik</dt><dd>Cel jest dostępny za pośrednictwem równoważnego łącza lub kontrolki na tej samej stronie, która ma co najmniej 44 na 44 piksele CSS;</dd><dt>Śródliniowe</dt><dd>Cel znajduje się w zdaniu lub w bloku tekstu;</dd><dt>Kontrola programu użytkownika</dt><dd>Rozmiar obiektu docelowego jest określony przez program użytkownika (przeglądarkę) i nie jest modyfikowany przez autora;</dd><dt>Istotny</dt><dd>Szczególna prezentacja celu ma istotne znaczenie dla przekazywanych informacji.</dd></dl>",
  "2.5.6": "<p>Treści internetowe nie ograniczają możliwości korzystania z trybów wprowadzania danych dostępnych na platformie, z wyjątkiem sytuacji, w których ograniczenie jest istotne, wymagane do zapewnienia bezpieczeństwa treści lub wymagane do przestrzegania ustawień użytkownika.</p>",
  "3.1.1": "<p>Domyślny język naturalny każdej strony internetowej może zostać odczytany przez program komputerowy.</p>",
  "3.1.2": "<p>Język naturalny każdej części lub frazy zawartej w treści może zostać odczytany przez program komputerowy, z wyjątkiem nazw własnych, wyrażeń technicznych, słów w nieokreślonym języku oraz słów i fraz, które stanowią część żargonu w bezpośrednio otaczającym je tekście.</p>",
  "3.1.3": "<p>Istnieje mechanizm, za pomocą którego można sprawdzić definicje słów użytych w nietypowy lub ograniczony sposób, w tym idiomów i żargonu.</p>",
  "3.1.4": "<p>Istnieje mechanizm, za pomocą którego można sprawdzić znaczenie skrótów.</p>",
  "3.1.5": "<p>Jeśli dany tekst, po usunięciu nazw własnych i tytułów, wymaga umiejętności czytania na poziomie wyższym niż poziom gimnazjalny, istnieje dodatkowa treść wyjaśniająca lub oddzielna wersja, która nie wymaga większych umiejętności czytania.</p>",
  "3.1.6": "<p>Istnieje mechanizm, za pomocą którego można sprawdzić wymowę słów, których znaczenie jest niejasne w danym kontekście bez znajomości ich wymowy.</p>",
  "3.2.1": "<p>Przyjęcie fokusu przez dowolny komponent interfejsu użytkownika nie powoduje nieoczekiwanej zmiany kontekstu.</p>",
  "3.2.2": "<p>Zmiana ustawień jakiegokolwiek komponentu interfejsu użytkownika nie powoduje automatycznej zmiany kontekstu, chyba, że użytkownik został poinformowany o takim działaniu, zanim zaczął korzystać z komponentu.</p>",
  "3.2.3": "<p>Mechanizmy nawigacji, które powtarzają się na wielu stronach internetowych w ramach jednego zestawu stron internetowych, występują w tej samej względnej kolejności za każdym razem, gdy są powtarzane, chyba że zmiana jest inicjowana przez użytkownika.</p>",
  "3.2.4": "<p>Komponenty, które mają tę samą funkcjonalność w ramach jednego zestawu stron internetowych, są w taki sam sposób zidentyfikowane.</p>",
  "3.2.5": "<p>Zmiany kontekstu inicjowane są tylko na żądanie użytkownika lub istnieje mechanizm pozwalający na wyłączenie takich zmian.</p>",
  "3.3.1": "<p>Jeśli automatycznie zostanie wykryty błąd wprowadzania danych, system wskazuje błędny element, a użytkownik otrzymuje opis błędu w postaci tekstu.</p>",
  "3.3.2": "<p>Gdy w treści wymagane jest wprowadzenie danych przez użytkownika, zapewnione są etykiety lub instrukcje.</p>",
  "3.3.3": "<p>Jeśli automatycznie zostanie wykryty błąd wprowadzania danych i znane są sugestie korekty, wtedy użytkownik otrzymuje takie sugestie, chyba, że zagrażałoby to bezpieczeństwu treści lub zmieniło jej cel.</p>",
  "3.3.4": "<p>W przypadku stron internetowych, które powodują zobowiązania prawne, albo na których użytkownik przeprowadza transakcje finansowe, modyfikuje lub usuwa dane w systemach przechowywania danych, nad którymi ma kontrolę, albo udziela odpowiedzi na testy, co najmniej jedna z poniższych informacji jest prawdziwa:</p><dl><dt>Odwracalność</dt><dd>Wprowadzenie danych jest odwracalne.</dd><dt>Sprawdzanie</dt><dd>Dane wprowadzone przez użytkownika są sprawdzane pod kątem błędów, a użytkownik ma możliwość wprowadzenia poprawek.</dd><dt>Potwierdzenie</dt><dd>Istnieje mechanizm sprawdzania, potwierdzania oraz korekty informacji przed jej ostatecznym wysłaniem.</dd></dl>",
  "3.3.5": "<p>Istnieje pomoc kontekstowa.</p>",
  "3.3.6": "<p>Dla stron internetowych, które wymagają od użytkownika wprowadzania informacji, przynajmniej jedno z poniższych założeń jest prawdziwe:</p><dl><dt>Odwracalność</dt><dd>Wprowadzenie danych jest odwracalne.</dd><dt>Sprawdzanie</dt><dd>Dane wprowadzone przez użytkownika są sprawdzane pod kątem błędów, a użytkownik ma możliwość wprowadzenia poprawek.</dd><dt>Potwierdzenie</dt><dd>Istnieje mechanizm sprawdzania, potwierdzania oraz korekty informacji przed jej ostatecznym wysłaniem.</dd></dl>",
  "4.1.1": "<p>W treści wprowadzonej przy użyciu języka znaczników, elementy posiadają kompletne znaczniki początkowe i końcowe, elementy są zagnieżdżane według swoich specyfikacji, nie posiadają zduplikowanych atrybutów, a wszystkie ID są unikalne, z wyjątkiem przypadków, kiedy specyfikacja zezwala na wyżej wymienione cechy.</p><blockquote><p><strong>Uwaga</strong></p><p>Początkowe i końcowe znaczniki, w których brak kluczowych znaków, takich, jak zamykający nawias ostry lub pytajnik błędnie dopasowany do atrybutu wartości, nie są uznawane za kompletne znaczniki.</p></blockquote>",
  "4.1.2": "<p>Dla wszystkich komponentów interfejsu użytkownika (w tym, ale nie tylko, elementów formularzy, łączy oraz komponentów wygenerowanych przez skrypty) nazwa oraz rola mogą być określone programowo; stan, właściwości oraz wartości, które mogą być ustawione przez użytkownika, mogą również być ustawione programowo; powiadomienie o zmianach w tych elementach dostępne jest dla programów użytkownika, w tym technologii wspomagających.</p><blockquote><p><strong>Uwaga</strong></p><p>To kryterium sukcesu jest przede wszystkim dla autorów stron internetowych, którzy opracowują lub skryptują własne komponenty interfejsu użytkownika. Na przykład, standardowe kontrolki HTML już spełniają to kryterium, gdy są używane zgodnie ze specyfikacją.</p></blockquote>",
  "4.1.3": "<p>W treści wprowadzonej przy użyciu języka znaczników komunikaty o stanie mogą być programowo określane poprzez role lub właściwości, dzięki czemu mogą być prezentowane użytkownikowi za pomocą technologii wspomagających bez uzyskiwania fokusu.</p>"
};

/** Normative Polish definitions from the WCAG 2.1 glossary, as sanitized HTML, keyed by term. */
export const wcagGlossary: Readonly<Record<string, string>> = {
  "alternatywa dla mediów opartych na czasie": "<p>dokument zawierający prawidłowo uporządkowany tekst przedstawiający informacje przekazywane w medium opartym na czasie wizualnie i dźwiękowo oraz uwzględniający końcowy stan interakcji z tym medium</p><blockquote><p><strong>Uwaga</strong></p><p>Scenariusz użyty do stworzenia zsynchronizowanych multimediów może być objęty taką definicją tylko wtedy, gdy został poprawiony tak, by odpowiadać dokładnej końcowej wersji multimediów po zakończeniu edycji.</p></blockquote>",
  "animacja ruchowa": "<p>dodanie kroków między warunkami, aby stworzyć iluzję ruchu lub dać wrażenie płynnego przejścia</p><p><em>Przykład:</em> Na przykład element, który przesuwa się na miejsce lub zmienia rozmiar podczas pojawiania się, jest uważany za animowany. Element, który pojawia się natychmiast bez przejścia, nie używa animacji. Animacja ruchowa nie obejmuje zmian koloru, rozmycia ani krycia.</p>",
  "audio": "<p>technologia powielania dźwięku</p><blockquote><p><strong>Uwaga</strong></p><p>Dźwięk może być tworzony syntetycznie (w mowa syntetyczna), nagrywany z dźwięków świata rzeczywistego lub na oba sposoby.</p></blockquote>",
  "audiodeskrypcja": "<p>narracja dodana do ścieżki dźwiękowej w celu opisania istotnych szczegółów obrazu, które nie mogą być zrozumiane z samej głównej ścieżki dźwiękowej</p><blockquote><p><strong>Uwaga</strong></p><p>Dźwiękowy opis materiału wideo zapewnia informacje o akcji, postaciach, zmianie scenerii, tekstach wyświetlanych na ekranie i innych treściach wizualnych.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>W standardowym opisie audio narracja jest dodawana w przerwach między dialogami (zobacz także rozszerzona audiodeskrypcja).</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Jeśli wszystkie informacje o wideo są już zapewnione przez podstawową ścieżkę dźwiękową, dodatkowa audiodeskrypcja jest zbędna.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Nazywana również „opisem wideo”, „narracją opisową” i „narracją dźwiękową”.</p></blockquote>",
  "audiodeskrypcja rozszerzona": "<p>audiodeskrypcja, dodawana do materiału wideo poprzez zatrzymanie odtwarzacza (pauza), dzięki czemu jest czas na wstawienie dodatkowego opisu.</p><blockquote><p><strong>Uwaga</strong></p><p>Ta technika jest stosowana tylko wówczas, gdy sensu materiału wideo nie da się zachować bez dodatkowej audiodeskrypcji, a przerwy pomiędzy dialogami i narracją są zbyt krótkie.</p></blockquote>",
  "bezczynność użytkownika": "<p>każdy nieprzerwany okres, w którym nie występują żadne działania użytkownika</p><p>Sposób śledzenia jest określany przez stronę internetową lub aplikację.</p>",
  "blok tekstu": "<p>więcej tekstu niż jedno zdanie</p>",
  "błąd wprowadzania danych": "<p>informacja wprowadzona przez użytkownika, która nie jest akceptowana przez system</p><blockquote><p><strong>Uwaga</strong></p><p>Dotyczy:</p><ol><li>Informacji, które są wymagane przez stronę internetową, a pominięte przez użytkownika.</li><li>Informacji wprowadzonych przez użytkownika, ale w niewłaściwym formacie lub o niedopuszczalnej wartości.</li></ol></blockquote>",
  "błysk": "<p>para przeciwstawnych względnych luminancji, która może u niektórych osób wywołać atak padaczki, jeżeli efekt ten ma odpowiednie natężenie i zmienia się z pewną określoną częstotliwością.</p><blockquote><p><strong>Uwaga</strong></p><p>Zobacz informacje o granicznych wartościach ogólnych błysków i czerwonych błysków, aby dowiedzieć się, które błyski są niedopuszczalne.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Zobacz także migotanie.</p></blockquote>",
  "CAPTCHA": "<p>skrót od \" Completely Automated Public Turing test to tell Computers and Humans Apart \" (całkowicie automatyczny publiczny test Turinga do odróżniania komputerów od ludzi)</p><blockquote><p><strong>Uwaga</strong></p><p>Test CAPTCHA najczęściej polega na przepisaniu przez użytkownika tekstu ze zniekształconego obrazu lub nagrania dźwiękowego.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Test Turinga to każdy system testów, który został zaprojektowany w celu odróżnienia człowieka od komputera. Został tak nazwany na cześć słynnego informatyka Alana Turinga. Pojęcie to sformułowane zostało na Uniwersytecie Carnegie Mellon.</p></blockquote>",
  "cel": "<p>obszar wyświetlacza, który zaakceptuje akcję wskaźnika, taki jak obszar interaktywny komponentu interfejsu użytkownika</p><blockquote><p><strong>Uwaga</strong></p><p>Jeżeli dwa lub więcej celów dotykowych nakładają się na siebie, pokrywający się obszar nie powinien być uwzględniany przy pomiarze wielkości celu, chyba że nakładające się cele wykonują tę samą czynność lub otwierają tę samą stronę.</p></blockquote>",
  "cel łącza": "<p>oczekiwany skutek aktywacji łącza</p>",
  "czysto dekoracyjny": "<p>służący jedynie w celu ozdobienia, nie niosący ze sobą żadnej informacji lub funkcjonalności</p><blockquote><p><strong>Uwaga</strong></p><p>Tekst jest czysto dekoracyjny, jeżeli słowa mogą być swobodnie przemieszczane lub podmieniane bez zmiany celu, jakiemu służy.</p></blockquote><p><em>Przykład:</em> Na okładce słownika znajdują się przypadkowe słowa wydrukowane w jasnym kolorze, pozostające w tle.</p>",
  "dostosowany wizualnie": "<p>czcionki, wielkość, kolor i tło mogą być ustawione</p>",
  "dotyk jednopunktowy": "<p>wprowadzanie danych dotykiem, które działa z jednym punktem kontaktu z ekranem, w tym pojedyncze stuknięcia i kliknięcia, podwójne stuknięcia i kliknięcia, długie naciśnięcia i gesty oparte na ścieżce</p>",
  "duży tekst": "<p>tekst o wielkości przynajmniej 18 punktów lub 14 punktów, ale pogrubiony lub odpowiadające im wielkością znaki alfabetu chińskiego, japońskiego i koreańskiego (CJK).</p><blockquote><p><strong>Uwaga</strong></p><p>Czcionki ze szczególnymi wykończeniami albo rzadko spotykanymi elementami i cechami, które ograniczają rozpoznawalność kształtów znaków są trudniejsze do odczytania, szczególnie przy obniżonym kontraście.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Rozmiar tekstu oznacza rozmiar, w którym treść jest dostarczana użytkownikowi. Nie dotyczy to rozmiaru ustawionego przez użytkownika.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Rozmiar tekstu widziany przez użytkownika zależy zarówno od rozmiaru zdefiniowanego przez autora strony, jak i od rozmiaru wyświetlacza i ustawień oprogramowania użytkownika. W większości wypadków 14 pt i 18 pt odpowiadają około 1.2 i 1.5 em lub 120% i 150% rozmiaru tekstu podstawowego (przyjmując rozmiar podstawowy za 100%), ale autorzy powinni się upewnić, że tak jest w ich przypadku. Jeżeli rozmiar tekstu jest podany w jednostkach względnych, to rozmiar tekstu do wyświetlenia jest obliczany przez oprogramowanie użytkownika. Rozmiar tekstu wyrażony w punktach może zostać pobrany z oprogramowania użytkownika albo obliczony na podstawie danych metrycznych wykonanych analogicznie do oprogramowania użytkownika, w celu sprawdzenia spełnienia kryterium sukcesu. Użytkownicy słabowidzący powinni mieć możliwość dokonania odpowiednich ustawień.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>W przypadku korzystania z tekstu, w którym nie określono rozmiaru tekstu, przeglądarki powinny dla najmniejszej czcionki tekstu używać rozsądnego rozmiaru. Jeżeli dla nagłówka poziomu 1 przeglądarki stosują rozmiar 14 pt pogrubioną lub większą, można przyjąć, że jest to powiększony tekst. Względne skalowanie może być wyliczane na podstawie domyślnych rozmiarów w podobny sposób.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Rozmiar 14 pt i 18 pt został przyjęty dla alfabetu łacińskiego jako minimalny duży rozmiar (14 pt) oraz powiększony standardowy (18 pt). Dla innych alfabetów, na przykład CJK, podobne rozmiary mogą być uznane za minimalny duży tekst druku, a następny większy rozmiar, za standardowy duży tekst druku.</p></blockquote>",
  "etykieta": "<p>tekst lub inny komponent z tekstem alternatywnym, który jest prezentowany użytkownikowi w celu identyfikacji komponentu w treści internetowej</p><blockquote><p><strong>Uwaga</strong></p><p>Etykieta jest widoczna dla wszystkich użytkowników, podczas gdy nazwa może być przekazywana tylko technologiom wspomagającym. W wielu przypadkach (choć nie we wszystkich) etykieta i nazwa są takie same.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Pojęcie etykiety nie ogranicza się tylko do elementu „label” w HTML.</p></blockquote>",
  "funkcjonalność": "<p>procesy i efekty osiągalne w wyniku działań użytkownika</p>",
  "gdy naciskane": "<p>zdarzenie dotykowe, które następuje potem, gdy bodziec wyzwalający wskaźnik naciska punkt interaktywny</p><p>Zdarzenie może mieć na różnych platformach różne nazwy, takie jak „touchstart” lub „mousedown”.</p>",
  "graniczne wartości dowolnych błysków i czerwonych błysków": "<p>błysk, albo szybko zmieniająca się sekwencja obrazów są poniżej granicznych wartości (tzn. treść <strong>jest zgodna</strong> z wytycznymi), jeżeli poniższe punkty przyjmują wartość „prawda”:</p><ol><li>nie występują więcej niż trzy <strong>błyski dowolne</strong> i/lub nie więcej niż trzy <strong>czerwone błyski</strong> w ciągu sekundy; lub</li><li>łączny obszar błysków pojawiających się jednocześnie nie przekracza 0,006 sterydianów w obrębie 10 stopni pola widzenia monitora (25% na każde 10 stopni pola widzenia monitora) dla osoby patrzącej na monitor z przeciętnej odległości.</li></ol><p>gdzie:</p><ul><li><strong>dowolny błysk</strong> jest zdefiniowany jako para przeciwnych zmian ze względną luminacją wynoszącą 10% lub więcej największej względnej luminancji, gdzie relatywna luminancja ciemniejszego z obrazów wynosi poniżej 0,80; i gdzie wzrost „pary przeciwnych zmian” łączy się ze zwiększeniem a następnie zmniejszeniem lub odwrotnie, a</li><li><strong>czerwony błysk</strong> jest zdefiniowany jako jakakolwiek para przeciwstawnych przejść zawierających ostrą/nasyconą czerwień.</li></ul><p><em>Wyjątek:</em> Błyskanie, które jest spokojne, zbalansowane, na wzór szumu lub szachownicy z „polami” mniejszymi niż 0,1 stopnia (pola widzenia przy przeciętnej odległości od monitora) umieszczone po boku nie przekraczają wartości granicznych.</p><blockquote><p><strong>Uwaga</strong></p><p>Przy przeciętnym oprogramowaniu i zawartości sieci, przy użyciu prostokąta o rozmiarze 341 x 256 pixeli na powierzchni ekranu, kiedy zawartość oglądana jest przy rozdzielczości 1024 x 768 pixeli da w przybliżeniu 10 stopni pola widzenia dla standardowych rozmiarów monitorów i standardowej odległości patrzenia na nie (na przykład 22-26 cali odległości, przy ekranie wielkości 15-17 cali). (Wyższe ustawienia rozdzielczości pokazujące to samo renderowanie zawartości daje mniejsze i bezpieczniejsze obrazy, tak więc niższe ustawienia rozdzielczości stosuje się, żeby zdefiniować progowanie).</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Przejście oznacza zmianę we względnej luminancji (lub relatywna luminancja/kolor w czerwonym błysku) pomiędzy sąsiadującymi szczytami i dolinami w obrębie relatywnej luminancji (lub relatywna luminancja/kolor w czerwonym błysku) w krótkim czasie. Błyśnięcie składa się z dwóch przeciwnych przejść.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Ta robocza definicja dla „ <strong>pary przeciwstawnych przejść zawierających ostrą/nasyconą czerwień</strong> ” obowiązuje wówczas, kiedy dla jednego lub obu stanów zaangażowanych w każde z przejść, R/(R+ G + B) &gt;= 0.8, a zmiana wartości (R-G-B)x320 wynosi &gt; 20 (ujemne wartości dla (R-G-B)x320 ustawionych na zero) dla obu przejść. R, G, B mają wartości 0-1 tak, jak zostało to określone w definicji „relatywnej luminancji”. [HARDING-BINNIE]</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Dostępne są narzędzia do analizy obrazu video, pod kątem granicznych wartości błysków. Nie trzeba jednak narzędzi, żeby osiągnąć te warunki, jeżeli migotanie jest równe lub mniejsze 3 mrugnięciom na sekundę. Zawartość przechodzi wówczas automatycznie (zobacz pkt 1 i 2 powyżej).</p></blockquote>",
  "idiom": "<p>fraza, której znaczenia nie da się wydedukować przez zrozumienie pojedynczych słów, a specyficznych słów nie da się zmienić bez utraty sensu</p><blockquote><p><strong>Uwaga</strong></p><p>Idiomów nie da się przetłumaczyć dosłownie — słowo po słowie, bez utraty ich kulturowego lub językowego znaczenia.</p></blockquote><p><em>Przykład:</em> W języku angielskim idiom: \" It rains cats and dogs \" dosłownie tłumacząc \"pada kotami i psami\" oznacza, że pada silny deszcz, leje. Polski odpowiednik: „Leje jak z cebra\".</p><p><em>Przykład:</em> W języku japońskim fraza \" さじを投げる \" tłumaczona dosłownie oznacza „on rzuca łyżką”, a w rzeczywistości oznacza to, że dana osoba nie dała sobie z czymś rady i poddała się.</p><p><em>Przykład:</em> W języku holenderskim, „ Hij ging met de kippen op stok \" dosłownie tłumacząc oznacza „pójść na grzędę z kurczakami”. W rzeczywistości oznacza to położyć się wcześnie spać.</p>",
  "informacyjne": "<p>tylko do celów informacyjnych i nie jest wymagana dla osiągnięcia zgodności</p><blockquote><p><strong>Uwaga</strong></p><p>Treść niezbędną dla osiągnięcia zgodności uznaje się za „ normatywną ”.</p></blockquote>",
  "interfejs klawiaturowy": "<p>interfejs używany przez oprogramowanie do obsługi wciśnięć klawiszy</p><blockquote><p><strong>Uwaga</strong></p><p>Interfejs klawiaturowy pozwala użytkownikowi na obsługę programów za pomocą klawiatury nawet wówczas, gdy dane urządzenie nie posiada klawiatury.</p><p><em>Przykład:</em> Urządzenia z dotykowymi ekranami posiadają wbudowane w system interfejsy klawiatury, jak również możliwość podłączenia zewnętrznych klawiatur. Aplikacje uruchamiane na takim urządzeniu obsługują zarówno zewnętrzną klawiaturę, jak i inne aplikacje symulujące klawiatury, w tym interpretery pisma ręcznego i systemy do przetwarzania mowy na tekst z wbudowaną symulacją klawiatury.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Operacje wykonywane w aplikacjach lub fragmentach aplikacji wykonywane za pomocą klawiszy symulujących mysz, np. klawisze myszy, nie są kwalifikowane jako wykonywane przez interfejs klawiaturowy, ponieważ operacje wykonywane są poprzez interfejs wskaźnika myszy, a nie klawiatury.</p></blockquote>",
  "istotny": "<p>jeżeli taki element zostanie usunięty, może to całkowicie zmienić informację lub funkcjonalność treści, <strong>a</strong> informacja i funkcjonalność nie mogą zostać osiągnięte w inny sposób, zapewniający zgodność</p>",
  "język migowy": "<p>język stosujący kombinację gestów dłoni i ramion, mimiki twarzy i pozycji ciała, w celu przekazania informacji.</p>",
  "język naturalny": "<p>język mówiony, pisany lub język migowy (znaków zarówno wizualnych, jak dotykowych) służący do komunikowania się między ludźmi.</p><blockquote><p><strong>Uwaga</strong></p><p>Zobacz także język migowy.</p></blockquote>",
  "komunikat o stanie": "<p>zmiana treści, która nie jest zmianą kontekstu i która dostarcza użytkownikowi informacji o powodzeniu lub wynikach działania, o stanie oczekiwania aplikacji, o postępie procesu lub o istnieniu błędów.</p>",
  "komponent interfejsu użytkownika": "<p>fragment treści internetowej odbierany przez użytkownika jako pojedyncza kontrolka dla określonej funkcji</p><blockquote><p><strong>Uwaga</strong></p><p>Wiele komponentów interfejsu użytkownika może być implementowanych w postaci pojedynczego elementu. Tutaj komponenty nie są związane z konkretną techniką programistyczną, a raczej z tym, co użytkownik odbiera jako pojedynczą kontrolkę.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Do komponentów interfejsu użytkownika należą elementy formularzy i linków, jak również komponenty generowane przez skrypty.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>To, co jest tutaj rozumiane jako „komponent” lub „komponent interfejsu użytkownika” jest również czasami nazywane „elementem interfejsu użytkownika”.</p></blockquote><p><em>Przykład:</em> Aplet posiada „kontrolkę” pozwalającą na przesuwanie treści po linii lub stronie albo na swobodny dostęp. Każdy aplet ma własną nazwę i może być używany niezależnie, jak również może być traktowany jak komponent interfejsu użytkownika.</p>",
  "konkretne odczucie zmysłowe": "<p>doznanie zmysłowe, które nie jest czysto dekoracyjne, a jego celem podstawowym nie jest przekazanie ważnej informacji lub spełnienie konkretnej funkcji.</p><p><em>Przykład:</em> Gra solo na flecie, sztuka wizualna, itd.</p>",
  "kontekst łącza określony programowo": "<p>dodatkowe informacje, które mogą być określone programowo na podstawie relacji między łączem oraz tekstem przyległym do łącza, i przedstawione użytkownikom na różne sposoby.</p><p><em>Przykład:</em> W języku HTML informacje, które można programowo określić z kontekstu łącza, obejmują tekst, który znajduje się w tym samym akapicie, na tej samej liście albo w komórce tabeli, co łącze, lub w komórce nagłówka tabeli, która jest powiązana z komórką tabeli, w której znajduje się łącze.</p><blockquote><p><strong>Uwaga</strong></p><p>Ponieważ czytnik ekranu (ang. screen reader) interpretuje interpunkcję, może też podać kontekst bieżącego zdania, kiedy fokus znajdzie się na łączu w tym zdaniu.</p></blockquote>",
  "kontrolowane przez użytkownika": "<p>dane, które mają być dostępne dla użytkowników</p><blockquote><p><strong>Uwaga</strong></p><p>Nie odnosi się to do takich rzeczy jak dzienniki internetowe i dane z monitoringu wyszukiwarek.</p></blockquote><p><em>Przykład:</em> Pola nazwy i adresu w formularzu konta użytkownika.</p>",
  "mechanizm": "<p>procedura lub technika prowadząca do osiągnięcia rezultatu</p><blockquote><p><strong>Uwaga</strong></p><p>Mechanizm może być dostarczany bezpośrednio w treści albo może być oparty zarówno na platformie, jak i na oprogramowaniu użytkownika, w tym na technologiach wspomagających.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Mechanizm wymaga spełnienia wszystkich kryteriów sukcesu żądanych dla danego poziomu.</p></blockquote>",
  "migotanie": "<p>naprzemienna zmiana stanu wizualnego w celu zwrócenia uwagi</p><blockquote><p><strong>Uwaga</strong></p><p>Zobacz także błysk. W przypadku odpowiedniej wielkości, odpowiedniej jasności oraz odpowiedniej częstotliwości, migotanie może być zakwalifikowane jako błyskanie.</p></blockquote>",
  "multimedia alternatywne dla tekstu": "<p>multimedia, które przekazują nie więcej informacji, niż bezpośrednio prezentowany tekst lub tekst alternatywny</p><blockquote><p><strong>Uwaga</strong></p><p>Multimedia alternatywne dla tekstu są dostarczane tym, dla których przydatne jest korzystanie z alternatywy dla tekstu. Multimedia alternatywne dla tekstu to: nagrania dźwiękowe, nagrania wideo (w tym język migowy) lub nagrania audiowizualne.</p></blockquote>",
  "na żywo": "<p>informacja przechwytywana z wydarzeń pochodzących z rzeczywistego świata, transmitowana bezpośrednio do odbiorcy, z opóźnieniem zależnym wyłącznie od nadawcy</p><blockquote><p><strong>Uwaga</strong></p><p>Opóźnienie zależne od nadawcy to krótkie (najczęściej automatyczne) opóźnienie, niezbędne na przykład w celu dania nadawcy czasu na kolejkowanie lub cenzurowanie treści wizualnej lub dźwiękowej. Opóźnienie to nie jest wystarczające, by nadawaną treść poddawać poważniejszej edycji.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Jeżeli informacja jest całkowicie generowana przez komputer, to nie jest informacją na żywo.</p></blockquote>",
  "nagranie": "<p>Informacja, która nie jest transmitowana na żywo</p>",
  "napisy rozszerzone": "<p>zsynchronizowana z obrazem alternatywa tekstowa dla treści dźwiękowych, zarówno mowy, jak i innych odgłosów, niezbędnych do zrozumienia przekazu multimedialnego</p><blockquote><p><strong>Uwaga</strong></p><p>Napisy rozszerzone mają formę podobną do napisów dialogowych, z tą różnicą, że oprócz treści wypowiedzi osób przekazują opis sytuacji pozadialogowej - dodatkowe informacje, potrzebne do zrozumienia treści programu, takie jak identyfikacja mówiących, informacje o istotnych sygnałach dźwiękowych, np. śmiechu, trzaskaniu drzwi, muzyce, oddaleniu, miejscu akcji. Stąd określenie „rozszerzone”.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Ze względu na zastosowane rozwiązania techniczne napisy dzielimy na <strong>zamknięte</strong> i <strong>otwarte</strong>.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Napisy zamknięte (ang. <em>closed caption, CC</em>) to napisy w odrębnym strumieniu tekstowym, które mogą być w niektórych odtwarzaczach włączane i wyłączane.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Napisy otwarte (<em>open caption OC</em>) to wszelkie napisy, których nie można wyłączyć. Na przykład, jeżeli są ekwiwalentem obrazów tekstu osadzonego w wideo.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Napisy nie powinny zasłaniać istotnych informacji w filmie.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>W niektórych krajach napisy rozszerzone nazywa się podpisami (<em>subtitles</em>).</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Audiodeskrypcja może, ale nie musi posiadać napisów rozszerzonych, ponieważ sama w sobie zawiera opis zawartości tego, co przedstawione jest w sposób wizualny.</p></blockquote>",
  "nawigowane sekwencyjnie": "<p>nawigowanie po stronie za pomocą interfejsu klawiaturowego w kolejności określonej dla przenoszenia fokusu</p>",
  "nazwa": "<p>tekst, po którym oprogramowanie może zidentyfikować obiekty w treści</p><blockquote><p><strong>Uwaga</strong></p><p>Nazwa może być ukryta i przekazywana tylko poprzez technologie wspomagające, w odróżnieniu od etykiet, które są prezentowane wszystkim użytkownikom. W niektórych, ale nie wszystkich wypadkach, etykieta i nazwa są tożsame.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>To nie jest to samo, co atrybut „name” w HTML.</p></blockquote>",
  "normatywny": "<p>niezbędny dla zapewnienia zgodności</p><blockquote><p><strong>Uwaga</strong></p><p>Można zapewnić zgodność z takim dokumentem na różne dobrze zdefiniowane sposoby.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Treść oznaczona jako „ informacyjna ” lub nienormatywna nigdy nie jest wymagana dla zapewnienia zgodności.</p></blockquote>",
  "obraz tekstu": "<p>tekst, który jest renderowany w postaci nietekstowej (np. jako grafika) w celu uzyskania określonych efektów wizualnych</p><blockquote><p><strong>Uwaga</strong></p><p>Nie dotyczy to tekstu znajdującego się na obrazie, w którym ważna jest inna treść wizualna.</p></blockquote><p><em>Przykład:</em> Osoba znajdująca się na zdjęciu ma przyczepioną plakietkę ze swoim imieniem i nazwiskiem.</p>",
  "obsługiwana dostępność": "<p>obsługiwana przez technologie wspomagające oraz przez przeglądarki i inne programy użytkownika</p><p>Żeby zakwalifikować użycie technologii tworzenia treści internetowych jako obsługiwane przez dostępność, muszą być spełnione oba poniższe warunki:</p><ol><li><p><strong> Technologia treści internetowych musi współpracować z technologiami wspomagającymi </strong>. Oznacza to, że sposoby wykorzystywania tej technologii zostały przetestowane pod kątem współdziałania z technologiami wspomagającymi i umożliwiają odczytywanie treści w języku naturalnym</p><p><strong>ORAZ</strong></p></li><li><p><strong>Muszą istnieć łatwo osiągalne przez użytkowników narzędzia obsługujące tę technologię</strong> Oznacza to, że co najmniej jedno z czterech poniższych stwierdzeń jest prawdziwe:</p><ol><li><p>Taka technologia z założenia jest powszechnie obsługiwana przez programy użytkownika, które również obsługują dostępność (tak jak HTML i CSS);</p><p><strong>LUB</strong></p></li><li><p>Technologia jest obsługiwana za pomocą szeroko rozpowszechnionej wtyczki, która również obsługuje dostępność;</p><p><strong>LUB</strong></p></li><li><p>Treść strony jest dostępna dla zamkniętych środowisk, takich jak środowisko uniwersyteckie lub sieć korporacyjna, gdzie wymagany przez tę technologię program użytkownika i użyty do treści internetowych także obsługuje dostępność;</p><p><strong>LUB</strong></p></li><li><p>Programy użytkownika obsługujące technologię, obsługują dostępność i można je z łatwością pobrać lub zakupić w następujący sposób:</p><ul><li>osób z niepełnosprawnością nie kosztuje to więcej niż osoby pełnosprawne <strong>oraz</strong></li><li>są równie łatwe do znalezienia i nabycia przez osoby z niepełnosprawnością, jak i pełnosprawne.</li></ul></li></ol></li></ol><blockquote><p><strong>Uwaga</strong></p><p>Grupa Robocza WCAG i W3C nie precyzują ani sposobu, ani poziomu obsługi technologii treści internetowych przez technologie wspomagające, aby móc uznać dane technologie internetowe za obsługujące dostępność. Czytaj więcej: Level of Assistive Technology Support Needed for \"Accessibility Support\" (Poziom wsparcia technologii wspomagających potrzebny do „obsługi dostępności”).</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Technologie internetowe mogą być wykorzystywane, nawet jeśli nie obsługują dostępności, dopóki nie są uwzględniane w ocenie dostępności, a strona jako całość będzie zgodna z wymogami, w tym z Wymogiem zgodności: 4. Użycie technologii obsługujących dostępność oraz Wymogiem zgodności 5. Brak zakłóceń:</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Kiedy technologia używana jest w sposób obsługujący dostępność, nie oznacza to, że wszystkie jej komponenty i ich użycie będą obsługiwały dostępność. Większość technologii, w tym HTML, nie obsługuje dostępności w co najmniej jednym ze swoich komponentów lub sposobie użycia. Strony są zgodne z wytycznymi WCAG tylko wówczas, kiedy użycie technologii obsługującej dostępność, może być uwzględniane jako podstawa oceny zgodności z WCAG.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Opierając się na technologiach tworzenia treści internetowych, które mają wiele wersji, należy określić, która wersja obsługuje dostępność.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Jednym ze sposobów dotarcia przez twórców treści internetowych do zastosowań technologii, które obsługują dostępność, jest zapoznanie się z zestawieniami zastosowań udokumentowanych jako obsługujące dostępność (zobacz: Understanding Accessibility-Supported Web Technology Uses - Zrozumieć zastosowania technologii internetowych obsługujących dostępność). Autorzy, firmy, sprzedawcy technologii i inni mogą dokumentować sposoby korzystania z technologii treści internetowych obsługujące dostępność. Jednak dokumentacja wszystkich sposobów i metod zastosowania tych technologii w dokumentacji musiałyby odpowiadać powyższej definicji technologii treści WWW obsługujących dostępność.</p></blockquote>",
  "obszar roboczy": "<p>obiekt, w którym oprogramowanie użytkownika prezentuje treść</p><blockquote><p><strong>Uwaga</strong></p><p>Oprogramowanie użytkownika prezentuje treść poprzez jeden lub więcej obszarów roboczych. Do obszarów roboczych (operacyjnych) zaliczamy okna, ramki, głośniki, wirtualne okulary. Obszar roboczy może zawierać w sobie inny obszar roboczy (na przykład osadzone ramki). Komponenty interfejsu użytkownika generowane przez oprogramowanie użytkownika, jak podpowiedzi, menu i komunikaty, nie są obszarami roboczymi.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Obszar roboczy obejmuje powierzchnię wewnątrz obiektu, np. okna przeglądarki, z wyłączeniem pasków narzędzi, zakładek i podobnych elementów</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Obszar roboczy nazywany jest też obszarem operacyjnym.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Definicja jest oparta o słowniczek z User Agent Accessibility Guidelines 1.0 Glossary [ UAAG10 ].</p></blockquote>",
  "obszar kluczowy": "<p>postrzegalna, programowo określona część treści</p><blockquote><p><strong>Uwaga</strong></p><p>W HTML każdy obszar oznaczony jako punkt orientacyjny jest obszarem kluczowym.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Obszary kluczowe nazywane są również „regionami”.</p></blockquote>",
  "niejednoznaczny dla użytkowników": "<p>cel nie może być określony na podstawie treści łącza lub treści strony wyświetlanej równocześnie z łączem (tzn. że użytkownicy bez niepełnosprawności wiedzą, co kryje się pod danym łączem dopiero po kliknięciu na nie)</p><p><em>Przykład:</em> Słowo guawa w tym zdaniu „Najwięksi eksporterzy guawy” jest łączem. Tak umieszczone łącze może oznaczać przeniesienie do definicji guawy, listy eksporterów guawy lub zdjęcia przedstawiającego ludzi zbierających guawę. Dopóki łącze nie zostanie kliknięte, zarówno użytkownicy pełnosprawni, jak i z niepełnosprawnością, nie wiedzą, co się pod nim kryje.</p>",
  "określony programowo": "<p>takie przedstawienie danych przez oprogramowanie dostawcy, które pozwala różnym programom użytkownika, w tym technologiom wspomagającym, odczytać i przedstawić daną informację, w sposób, jakiego potrzebuje użytkownik</p><blockquote><p><strong>Uwaga</strong></p><p>Przedstawienie danych, w języku znaczników, z elementów i atrybutów, które są dostępne bezpośrednio dla najczęściej używanych technologii asystujących.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Przedstawienie za pomocą technologii – szczególnie struktury danych sformułowanych w języku innym niż język znaczników i nastawionych na technologie wspomagające poprzez API dostępność, które jest obsługiwane przez najczęściej spotykane technologie wspomagające.</p></blockquote>",
  "piksel CSS": "<p>kąt widzenia wynoszący około 0,0213 stopnia</p><p>Piksel CSS jest kanoniczną jednostką miary dla wszystkich długości i pomiarów w CSS. Jednostka ta jest niezależna od gęstości i różni się od rzeczywistych pikseli sprzętowych obecnych na wyświetlaczu. Programy użytkownika i systemy operacyjne powinny zapewnić, że piksel CSS jest ustawiony jak najbliżej wartości i jednostek piksela referencyjnego zdefiniowanego w CSS Values and Units Module Level 3 reference pixel [ css3-values ], który uwzględnia fizyczne wymiary wyświetlacza oraz zakładaną odległość oglądania (czynniki, których autorzy treści nie mogą określić).</p>",
  "podstawowy poziom edukacji": "<p>sześcioletni okres edukacji rozpoczynający się w wieku 5-7 lat, możliwie bez wcześniejszej edukacji</p><blockquote><p><strong>Uwaga</strong></p><p>Definicja oparta jest o Międzynarodową Standardową Klasyfikację Kształcenia [ UNESCO ].</p></blockquote>",
  "pomoc kontekstowa": "<p>tekst pomocy dostarczający informacji na temat aktualnie wykonywanej czynności</p><blockquote><p><strong>Uwaga</strong></p><p>Jasno sformułowane etykiety mogą być traktowane jak pomoc kontekstowa</p></blockquote>",
  "gimnazjalny poziom edukacji": "<p>dwu- lub trzyletni okres edukacji, zaczynający się po zakończeniu sześcioletniej szkoły, a kończący się dziewięć lat od rozpoczęcia edukacji podstawowej</p><blockquote><p><strong>Uwaga</strong></p><p>Definicja oparta jest o Międzynarodową Standardową Klasyfikację Kształcenia [ UNESCO ].</p></blockquote>",
  "prawidłowa kolejność odczytu": "<p>kolejność słów i akapitów zaprezentowana w taki sposób, żeby kolejność ich odczytu nie zmieniała sensu treści całego przekazu tekstowego</p>",
  "procedura": "<p>seria czynności użytkownika, gdzie każda czynność jest niezbędna do zakończenia działania</p><p><em>Przykład:</em> Zakończona sukcesem procedura korzystania ze stron sklepu internetowego wymaga od użytkownika obejrzenia alternatywnych produktów, cen i ofert, wybrania produktów, złożenia zamówienia, ustalenia warunków dostawy oraz podania informacji o wysyłce i płatności.</p><p><em>Przykład:</em> Strona rejestracji konta wymaga przejścia testu Turinga, a następnie wypełnienia formularza rejestracyjnego.</p>",
  "programowo ustawione": "<p>ustawione przez oprogramowanie wykorzystującego metody obsługiwane przez oprogramowanie użytkownika, w tym przez technologie wspomagające</p>",
  "program użytkownika": "<p>oprogramowanie umożliwiające pobieranie i przeglądanie treści internetowych</p><p><em>Przykład:</em> Przeglądarki internetowe, odtwarzacze multimediów, wtyczki oraz inne programy — również technologie wspomagające — które pomagają w wyszukiwaniu, przetwarzaniu i interakcji z treściami internetowymi.</p>",
  "przedstawianie": "<p>renderowanie treści w sposób, który jest postrzegalny dla użytkownika</p>",
  "punkt dotyku": "<p>niezależna od sprzętu reprezentacja urządzeń wejściowych, które mogą wskazywać określone współrzędne (lub zestaw współrzędnych) na ekranie, takie jak mysz, pióro lub kontakt dotykowy</p><p>Zobacz także Pointer Events pointer definition [ pointerevents ].</p>",
  "relacja": "<p>posiadające znaczenie powiązanie między różnymi elementami treści</p>",
  "rola": "<p>tekst lub liczba, poprzez którą oprogramowanie może określić funkcję komponentu w treści internetowej</p><p><em>Przykład:</em> Liczba, dzięki której można określić funkcję grafiki jako łącza, przycisku lub pola wyboru.</p>",
  "sekcja": "<p>samodzielna porcja pisanej treści, obejmująca jeden lub więcej powiązanych tematów lub myśli</p><blockquote><p><strong>Uwaga</strong></p><p>Sekcja może składać się z jednego lub więcej akapitów, a także zawierać grafikę, tabele, listy i podsekcje.</p></blockquote>",
  "skrót": "<p>skrócona wersja słowa, frazy lub nazwy, o ile skrót nie stał się częścią danego języka.</p><blockquote><p><strong>Uwaga</strong></p><p>dotyczy także inicjalizmów i akronimów, gdzie:</p></blockquote><ol><li><p><strong>inicjalizm</strong> to skrócona forma nazw i fraz, powstała z pierwszych liter lub sylab słów zawartych w danej nazwie lub frazie.</p><blockquote><p><strong>Uwaga</strong></p><p>Nie we wszystkich językach</p></blockquote><p><em>Przykład:</em> SNCF jest francuskim inicjalizmem, który zawiera pierwsze litery wyrazów Société Nationale des Chemins de Fer (nazwa francuskich kolei państwowych).</p><p><em>Przykład:</em> ESP (ang. extrasensory perception) to inicjalizm angielski oznaczający postrzeganie pozazmysłowe.</p></li><li><p><strong>akronim</strong> jest skróconą formą utworzoną z pierwszych liter lub części innych wyrazów do formy, którą można wymawiać jak wyraz.</p><p><em>Przykład:</em> NOAA jest akronimem utworzonym od pierwszych liter nazwy National Oceanic and Atmospheric Administration w USA.</p></li></ol><blockquote><p><strong>Uwaga</strong></p><p>Niektóre firmy mają nazwy pochodzące od akronimów. W takim wypadku nowa nazwa składa się z liter (np. Ecma) i wówczas słowo to nie jest traktowane jak skrót.</p></blockquote>",
  "skrót klawiaturowy": "<p>alternatywny sposób wykonania jakiejś akcji przez naciśnięcie jednego lub więcej klawiszy</p>",
  "wiarygodna podstawa zgodności (technologia)": "<p>treść nie będzie zgodna, jeżeli taka technologia zostanie wyłączona z oceny lub nie jest obsługiwana</p>",
  "stan": "<p>cecha dynamiczna wyrażająca właściwości komponentu interfejsu użytkownika, która może ulec zmianie w odpowiedzi na działanie użytkownika lub zautomatyzowane procesy</p><p>Stany nie mają wpływu na charakter elementu, ale reprezentują dane powiązane z tym komponentem lub możliwościami interakcji z użytkownikiem. Przykłady obejmują fokus (skupienie), najechanie wskaźnikiem myszki, wybrany (zaznaczony), wciśnięty, sprawdzony, odwiedzony/nieodwiedzony oraz rozwinięty/zwinięty.</p>",
  "strona internetowa": "<p>nieosadzony zasób uzyskany z pojedynczego identyfikatora URI za pomocą protokołu HTTP wraz z wszelkimi innymi zasobami użytymi do renderowania strony w programie użytkownika lub takimi, które potencjalnie mogą być użyte do renderowania</p><blockquote><p><strong>Uwaga</strong></p><p>Mimo że każdy z „pozostałych zasobów” mógłby być renderowany razem z podstawowym zasobem, to niekoniecznie muszą być renderowane równocześnie.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Dla zgodności z wytycznymi zasób musi być „nieosadzony”, czyli występować w taki sposób, by nie był uwzględniany jako strona internetowa.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Zarówno pojedyncza strona internetowa, jak i serwis złożony z wielu stron internetowych, czyli witryna, potocznie określane są jako „strona internetowa”. Ta definicja ogranicza stosowanie terminu „strona internetowa” tylko do zasobu uzyskanego z <strong>pojedynczego identyfikatora URI</strong>, a więc do jednej, pojedynczej samodzielnej strony internetowej albo jednej, pojedynczej strony w witrynie złożonej z wielu stron.</p></blockquote><p><em>Przykład:</em> Zasób sieciowy wraz ze wszystkimi osadzonymi obrazami i multimediami.</p><p><em>Przykład:</em> Internetowy program pocztowy zbudowany w technologii AJAX (asynchroniczny Java Script i XML). Program znajduje się pod adresem http://przyklad.com/mail, ale posiada skrzynkę odbiorczą, kontakty i kalendarz. Wszystkie łącza lub przyciski są zaprojektowane w sposób pozwalający na wyświetlanie skrzynki, kontaktów i kalendarza bez zmiany adresu URI.</p><p><em>Przykład:</em> Konfigurowalny portal internetowy, w którym użytkownik może wybrać wyświetlaną treść spośród różnych modułów.</p><p><em>Przykład:</em> Kiedy wprowadzasz np. adres \"http://zakupy.przyklad.com/\" w przeglądarce, wchodzisz do wyglądającego jak film sklepu, po którym możesz się poruszać, zabierać towar z półek i umieszczać go w wózku przed sobą. Kliknięcie na produkt powoduje wyświetlenie go wraz ze specyfikacją. Może to być jednostronicowy serwis lub jedna ze stron internetowych w serwisie internetowym.</p>",
  "struktura": "<ol><li>Sposób, w jaki poszczególne części strony internetowej są ułożone i połączone ze sobą; oraz</li><li>Sposób ułożenia zbioru stron internetowych.</li></ol>",
  "sztuka tekstowa": "<p>albo <em>ASCII art</em> - proste rysunki tworzone za pomocą znaków lub glifów układanych na obszarze o stałej szerokości kolumn oraz o stałej wysokości znaków (zazwyczaj z 95 możliwych do wydrukowania znaków zdefiniowanych przez ASCII). Ten sposób tworzenia grafiki, a raczej jej symbolizowania, nazywa się semigrafiką lub pseudografiką. <em>ASCII art</em> były początkowo tworzone z myślą o wydrukowaniu ich na drukarkach znakowych.</p>",
  "spełnienie kryterium sukcesu": "<p>kryterium sukcesu zastosowane do danej strony nie przyjmuje wartości „fałsz”</p>",
  "taka sama funkcjonalność": "<p>daje taki sam rezultat w przypadku zastosowania</p><p><em>Przykład:</em> Przycisk „wyślij” w jednym serwisie i przycisk „szukaj” w innym mogą mieć pole do wprowadzania wyrażenia, a następnie wyświetlają listę odnalezionych w serwisie informacji związanych z tym wyrażeniem. W takiej sytuacji oba mają taką samą funkcjonalność, chociaż nie są konsekwentnie etykietowane.</p>",
  "taka sama względna kolejność": "<p>taka sama pozycja względem innych elementów</p><blockquote><p><strong>Uwaga</strong></p><p>Uznaje się, że pozycje posiadają taką samą względną kolejność, nawet jeśli inne elementy zostały dodane lub usunięte z kolejności oryginalnej. Przykładowo, rozszerzenie menu nawigacji może wyświetlić dodatkowy poziom szczegółów, lub też druga sekcja nawigacji może zostać dodana do kolejności czytania.</p></blockquote>",
  "technologia (treści internetowych)": "<p>mechanizm kodowania danych, które mają być renderowane, odtwarzane lub wykonywane przez programy użytkownika</p><blockquote><p><strong>Uwaga</strong></p><p>Użyte w tych wytycznych wyrażenia „technologia internetowa” oraz słowo „technologia” (używane samodzielnie) odnoszą się do „technologii treści internetowych”.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Technologie treści internetowych mogą obejmować języki znaczników, formaty danych lub języki programowania, który może być używany samodzielnie, których autorzy mogą używać samodzielnie lub w połączeniu z innymi technologiami, żeby stworzyć ostatecznie wersje dla użytkownika, począwszy od statycznych stron internetowych, przez zsynchronizowane prezentacje multimedialne aż po dynamiczne aplikacje internetowe.</p></blockquote><p><em>Przykład:</em> Do typowych przykładów technologii treści internetowych zaliczamy między innymi HTML, CSS, SVG, PNG, PDF i JavaScript.</p>",
  "technologie wspomagające (w rozumieniu tego dokumentu)": "<p>sprzęt i oprogramowanie, które działa jako program użytkownika lub współdziała ze standardowymi programami użytkownika, aby zapewnić niezbędne osobom z niepełnosprawnościami funkcjonalności, przekraczające możliwości standardowych programów użytkownika;</p><blockquote><p><strong>Uwaga</strong></p><p>Inne nazwy: technologie asystujące, technologie pomocnicze;</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Funkcjonalności zapewniane przez technologie wspomagające obejmują alternatywny sposób prezentacji treści (np. mowa syntetyczna lub powiększenie obrazu), alternatywne sposoby wprowadzania danych (np. za pomocą głosu), dodatkowe mechanizmy nawigacji i orientacji oraz transformacji treści (np. w celu uczynienia tabel bardziej dostępnymi).</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Technologie wspomagające często komunikują się ze standardowymi aplikacjami za pośrednictwem specjalnych API.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Rozróżnienie pomiędzy popularnymi programami użytkownika a technologiami wspomagającymi nie jest oczywiste. Wiele programów użytkownika głównego nurtu posiada różne rozwiązania wspomagające osoby z niepełnosprawnościami. Główna różnica pomiędzy nimi polega na tym, że programy użytkownika głównego nurtu są ukierunkowane na szerokie i zróżnicowane grupy odbiorców, zarówno z niepełnosprawnościami, jak i bez niepełnosprawności. Natomiast technologie wspomagające skierowane są do wąsko zdefiniowanej populacji użytkowników z określonymi rodzajami niepełnosprawności. Wsparcie świadczone za pomocą technologii wspomagających jest zatem bardziej wyspecjalizowane i nakierowane na odbiorcę z konkretnymi potrzebami. Standardowe programy użytkownika mogą dostarczać technologiom wspomagającym niezbędnych funkcjonalności, takich jak pobieranie treści internetowych z obiektów programowych lub odwzorowanie kodu do postaci przyjaźniejszej dla tych technologii.</p></blockquote><p><em>Przykład:</em> Technologie wspomagające ważne w kontekście tego dokumentu to między innymi:</p><ul><li>powiększalniki ekranu i inne programy wspomagające czytanie wzrokowe, używane przez osoby ze wzrokowymi, percepcyjnymi i innymi niepełnosprawnościami związanymi z korzystaniem z druku, pozwalające na zmianę czcionek, rozmiaru, rozmieszczenia, koloru, synchronizujące tekst z głosem itp., w celu poprawienia czytelności wyświetlanego tekstu i obrazów;</li><li>czytniki ekranu, używane przez osoby niewidome do odczytu treści tekstowych za pomocą mowy syntetycznej lub brajla;</li><li>programy przetwarzające tekst na mowę syntetyczną, używane przez niektóre osoby z niepełnosprawnościami poznawczymi, językowymi i trudnościami w nauce w celu przekształcenia tekstu w mowę syntetyczną;</li><li>programy rozpoznające mowę, używane przez niektóre osoby z niepełnosprawnościami fizycznymi;</li><li>specjalne klawiatury, używane przez osoby z niektórymi niepełnosprawnościami fizycznymi, które symulują standardową klawiaturę (w tym klawiatury specjalne wyposażone we wskaźniki nagłowne, przełączniki, urządzenia dmuchnij/wciągnij (<em>sip-and-puff</em>) i inne specjalne urządzenia do wprowadzania danych);</li><li>specjalne wskaźniki, używane przez osoby z niektórymi rodzajami niepełnosprawności fizycznych w celu symulowania kursora myszy i naciskania przycisków.</li></ul>",
  "tekst": "<p>ciąg znaków, który można programowo określić, gdzie ciąg ten wyraża coś w języku naturalnym</p>",
  "tekst alternatywny": "<p>tekst skojarzony programowo z treścią nietekstową lub odnoszący się do tekstu programowo skojarzonego z treścią nietekstową. Tekst programowo skojarzony to taki tekst, którego położenie może być programowo określone w stosunku do treści nietekstowej.</p><p><em>Przykład:</em> Obraz wykresu jest opisany w następującym po nim akapicie. Krótki tekst alternatywny dla wykresu informuje, że takie objaśnienie znajduje się zaraz za nim (w kolejności treści).</p><blockquote><p><strong>Uwaga</strong></p><p>Więcej na ten temat: Understanding Text Alternatives (Zrozumieć tekst alternatywny).</p></blockquote>",
  "tłumaczenie w języku migowym": "<p>tłumaczenie języka, najczęściej mówionego, na język migowy</p><blockquote><p><strong>Uwaga</strong></p><p>Prawdziwe języki migowe są niezależnymi językami i nie mają nic wspólnego z językami mówionymi z danego kraju lub regionu.</p></blockquote>",
  "treść (treść internetowa)": "<p>informacje i wrażenia sensoryczne, które mają być przekazywane użytkownikowi za pośrednictwem programu użytkownika, w tym kod lub znaczniki definiujące strukturę, prezentację i interakcje</p>",
  "treść nietekstowa": "<p>każda treść, która nie jest sekwencją znaków, które mogą być programowo określone lub nie wyraża niczego w jakimkolwiek języku naturalnym</p><blockquote><p><strong>Uwaga</strong></p><p>Obejmuje to sztukę tekstową (ASCII art, będącą układanką złożoną ze znaków), emotikony, slang na forach (korzystający z zastępowania znaków) i obrazy przedstawiające tekst.</p></blockquote>",
  "treść uzupełniająca": "<p>dodatkowa treść ilustrująca lub wyjaśniająca treść podstawową</p><p><em>Przykład:</em> Dźwiękowa wersja strony internetowej.</p><p><em>Przykład:</em> Ilustracja kompletnej procedury.</p><p><em>Przykład:</em> Akapit podsumowujący główne wnioski i rekomendacje w jakichś badaniach.</p>",
  "tylko audio": "<p>prezentacja oparta na czasie zawierająca tylko dźwięk (bez wideo i bez interakcji)</p>",
  "tylko wideo": "<p>prezentacja oparta na czasie zawierająca tylko wideo (no audio i bez interakcji)</p>",
  "użyte w nietypowy lub ograniczony sposób": "<p>słowa użyte w sposób wymagający od użytkownika wiedzy, jaką konkretną definicję powinien zastosować, by prawidłowo zrozumieć treść.</p><p><em>Przykład:</em> Słowo „gig” oznacza coś innego w dyskusji na temat wykonania koncertu muzycznego, niż w artykule poświęconym pojemności dysków twardych, ale prawidłowe określenie definicji jest możliwe na podstawie kontekstu. Z drugiej strony, słowo „tekst” jest używane w WCAG w pewien bardzo specyficzny sposób i dlatego jego definicja znalazła się w słowniczku.</p>",
  "wersja alternatywna zapewniająca zgodność": "<p>to taka wersja, która</p><ol><li>jest zgodna z określonym poziomem oraz</li><li>zapewnia te same informacje i funkcjonalności w tym samym naturalnym języku, oraz</li><li>jest tak samo aktualna jak wersja niezgodna, oraz</li><li><p>dla której przynajmniej jeden z poniższych warunków jest spełniony:</p><ol><li>wersja zgodna jest osiągalna z wersji niezgodnej za pomocą mechanizmu obsługującego dostępność lub</li><li>niezgodna wersja jest osiągalna jedynie z wersji zgodnej, lub</li><li>wersja niezgodna może być osiągalna tylko z wersji zgodnej, o ile zawiera mechanizm osiągnięcia wersji zgodnej.</li></ol></li></ol><blockquote><p><strong>Uwaga</strong></p><p>W tej definicji „może być osiągalna tylko” oznacza, że zapewniony jest jakiś mechanizm, jak na przykład warunkowe przekierowanie, który uchroni użytkownika przed „osiągnięciem” (załadowaniem) niezgodnej wersji, dopóki nie przejdzie z wersji zgodnej.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Alternatywna wersja nie musi być identyczna, co do ilości stron z podstawową (np. może się składać z kilku podstron).</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Jeżeli dostępne są różne wersje językowe serwisu, to dla każdej powinny być zapewnione zgodne wersje.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Alternatywne wersje mogą być zapewniane dla różnych technologii lub grup odbiorców. Każda wersja powinna być zgodna w jak najwyższym stopniu. Jedna wersja powinna być w pełni zgodna, aby uzyskać Wymóg zgodności nr 1.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Zgodna wersja alternatywna nie musi znajdować się w zakresie zgodności, ani nawet w tym samym serwisie internetowym, jeżeli jest równie łatwo dostępna, jak jej wersja niezgodna.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Alternatywna wersja nie powinna być mylona z treścią uzupełniającą, która ma wspierać i rozszerzać wersję podstawową.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Ustawienie w preferencjach użytkownika, które pozwala na uzyskanie zgodnej wersji jest akceptowalnym mechanizmem dla osiągnięcia innej wersji, o ile mechanizm ustawień obsługuje dostępność.</p></blockquote><p>Czytaj więcej Understanding Conforming Alternate Versions (Zrozumieć alternatywne wersje zapewniające zgodność).</p>",
  "wideo": "<p>technologia poruszających się lub następujących po sobie obrazów</p><blockquote><p><strong>Uwaga</strong></p><p>Wideo może być stworzone za pomocą animacji lub fotografii, lub obu naraz.</p></blockquote>",
  "właściwość stylu": "<p>właściwość, której wartość określa sposób prezentacji (np. czcionka, kolor, rozmiar, lokalizacja, wypełnienie, głośność, synteza mowy) elementów treści w trakcie ich renderowania (np. na ekranie, przez głośnik, przez wyświetlacz brajlowski, przez programy użytkownika).</p><p>Właściwości stylu mogą mieć kilka źródeł:</p><ul><li>Domyślne style programu użytkownika: Domyślne wartości właściwości stylu stosowane w przypadku braku stylów autora lub użytkownika. Niektóre technologie treści internetowych określają domyślne renderowanie, inne nie;</li><li>Style autora: Wartości właściwości stylu ustawione przez autora jako część treści (np. style wbudowane, arkusze stylów autora);</li><li>Style użytkownika: Wartości właściwości stylu ustawione przez użytkownika (np. poprzez ustawienia interfejsu programu użytkownika, arkusze stylów użytkownika).</li></ul>",
  "współczynnik kontrastu": "<p>(L1 + 0.05) / (L2 + 0.05), gdzie</p><ul><li>L1 to relatywna luminancja oto relatywna luminancja jaśniejszego z kolorów, a</li><li>L2 to relatywna luminancja ciemniejszego z kolorów.</li></ul><blockquote><p><strong>Uwaga</strong></p><p>Współczynnik kontrastu zawiera się pomiędzy 1 i 21 (powszechnie zapisywanych 1:1 do 21:1).</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Ponieważ autor strony nie ma wpływu na sposób renderowania ustawiony przez użytkownika (np. wygładzanie czcionek lub antyaliasing), współczynnik kontrastu oblicza się jak dla wyłączonego antyaliasingu.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>W celu spełnienia kryterium sukcesu 1.4.3 i 1.4.6, kontrast jest mierzony z uwzględnieniem standardowego koloru tła, na którym wyświetlany jest tekst przy standardowym użyciu. Jeżeli kolor tła nie został zdefiniowany, przyjmuje się, że jest to kolor biały.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Kolor tła to określony kolor, na którym renderowany jest tekst przy normalnym użyciu. Błędem jest nie określenie koloru tła przy jednoczesnym określeniu koloru tekstu, ponieważ wówczas kolor tła jest nieznany i nie można sprawdzić, czy zachowany jest odpowiedni kontrast. Z tego samego powodu błędem jest nie określenie koloru tekstu przy jednoczesnym określeniu koloru tła.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Gdy litery wyświetlane są z obwódkami, obwódki takie mogą dodawać kontrastu i mogą być uwzględniane w obliczaniu kontrastu pomiędzy literami a ich tłem. Cienka obwódka jest traktowana jak litera. Szeroka obwódka wokół litery, jeżeli wypełnia wewnętrzne elementy liter, działa jak efekt halo i może być traktowana jak tło.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Wymagania WCAG mogą być zweryfikowane przez zestawienie par kolorów określonych przez autora dla typowego sposobu wyświetlenia strony. Autor nie musi brać pod uwagę nietypowych sposobów wyświetlania, na przykład przez zmianę kolorów zrealizowaną przez narzędzia użytkownika, chyba, że wynikają z kodu strony.</p></blockquote>",
  "wstrzymane": "<p>zatrzymane na żądanie użytkownika i nie wznawiane bez jego żądania</p>",
  "wydanie punktowe": "<p>wydanie zawierające poprawki do wersji głównej</p><blockquote><p><strong>Uwaga</strong></p><p>Numer wydania zawierającego poprawki znajduje się za numerem wydania głównego po kropce.</p></blockquote>",
  "wydarzenie w czasie rzeczywistym": "<p>wydarzenie, które a) trwa w tym samym czasie, co jego wyświetlenie i b) nie jest całkowicie generowane przez treść.</p><p><em>Przykład:</em> Transmisja internetowa z przedstawienia (odbywa się w tym samym czasie, gdy jest oglądane, a nie z nagrania).</p><p><em>Przykład:</em> Aukcja internetowa, podczas której użytkownicy składają oferty w tym samym czasie, gdy wyświetlana jest treść.</p><p><em>Przykład:</em> Interakcje ludzi w wirtualnym świecie za pośrednictwem awatarów (nie są automatycznie generowane i odbywają się w tym samym czasie, co oglądanie).</p>",
  "względna luminancja": "<p>względna jasność punktu w przestrzeni kolorów, znormalizowana do 0 dla najciemniejszego czarnego i 1 dla najjaśniejszego białego.</p><blockquote><p><strong>Uwaga</strong></p><p>Dla przestrzeni kolorów w standardzie sRGB względna luminancja koloru jest definiowana jako L = 0.2126 * <strong>R</strong> + 0.7152 * <strong>G</strong> + 0.0722 * <strong>B</strong> gdzie <strong>R</strong>, <strong>G</strong> i <strong>B</strong> zostały zdefiniowane jako:</p><ul><li>jeżeli RsRGB &lt;= 0.03928, wówczas <strong>R</strong> = RsRGB/12.92 lub <strong>R</strong> = ((RsRGB+0.055)/1.055) ^ 2.4</li><li>jeżeli GsRGB &lt;= 0.03928, wówczas <strong>G</strong> = GsRGB/12.92 lub <strong>G</strong> = ((GsRGB+0.055)/1.055) ^ 2.4</li><li>jeżeli BsRGB &lt;= 0.03928, wówczas <strong>B</strong> = BsRGB/12.92 lub <strong>B</strong> = ((BsRGB+0.055)/1.055) ^ 2.4</li></ul><p>oraz RsRGB, GsRGB i BsRGB są zdefiniowane jako:</p><ul><li>RsRGB = R8bit/255</li><li>GsRGB = G8bit/255</li><li>BsRGB = B8bit/255</li></ul><p>Znak „^” oznacza potęgowanie. (Równanie pochodzi z [ sRGB ] i [ IEC-4WD ]).</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Niemal wszystkie obecnie używane systemy kodują kolory w standardzie sRGB. O ile używany będzie inny standard kodowania kolorów do przetwarzania i wyświetlania, autor musi obliczać kolor na podstawie standardu sRGB. Jeżeli używa innego, zobacz Understanding Success Criterion 1.4.3 (Zrozumieć kryterium sukcesu 1.4.3).</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Jeżeli dithering odbywa się po dostarczeniu kolorów, bierze się pod uwagę kolory źródłowe. W wypadku kolorów wymieszanych na poziomie źródłowym, pod uwagę bierze się uśrednione wartości kolorów źródłowych (uśredniony R, uśredniony G i uśredniony B).</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Istnieją narzędzia, które automatycznie obliczają kontrast i błyski.</p></blockquote><blockquote><p><strong>Uwaga</strong></p><p>Istnieje wersja MathML dla wzorów względnej luminancji.</p></blockquote>",
  "zagrożenie": "<p>nagła, nieoczekiwana sytuacja lub zdarzenie, wymagające natychmiastowej reakcji dla ochrony zdrowia, bezpieczeństwa lub mienia.</p>",
  "zgodność": "<p>spełnienie wszystkich wymagań danej normy, wytycznych lub specyfikacji</p>",
  "zestaw stron internetowych": "<p>zbiór stron internetowych, które mają wspólny cel i które są tworzone przez tego samego autora, grupę lub organizację.</p><p><em>Przykład:</em> Przykładem jest publikacja podzielona na wiele stron internetowych, gdzie każda strona zawiera jeden rozdział lub inną znaczącą część pracy. Publikacja jest logicznie pojedynczą, ciągłą jednostką i zawiera funkcje nawigacyjne, które umożliwiają dostęp do pełnego zestawu stron.</p><blockquote><p><strong>Uwaga</strong></p><p>Różne wersje językowe będą traktowane jako różne zestawy stron internetowych.</p></blockquote>",
  "zmaksymalizowane okno ekranu": "<p>na najczęściej spotykanych rozmiarach monitorach komputerów stacjonarnych i laptopach z maksymalnym rozmiarem obszaru roboczego</p><blockquote><p><strong>Uwaga</strong></p><p>Ponieważ ludzie zazwyczaj korzystają ze swoich komputerów przez kilka lat, najlepiej jest nie polegać na najnowszych rozdzielczościach wyświetlaczy komputerów stacjonarnych/laptopów, ale wziąć pod uwagę przy dokonywaniu tej oceny typowe rozdzielczości monitorów komputerów stacjonarnych/laptopów na przestrzeni kilku lat.</p></blockquote>",
  "zmiany kontekstu": "<p>znaczące zmiany treści strony internetowej, które dokonywane bez świadomości użytkownika, mogą go dezorientować, jeżeli nie jest on w stanie oglądać całej strony jednocześnie</p><p>Zmiany kontekstu obejmują zmiany:</p><ol><li>w programie użytkownika;</li><li>obszaru roboczego;</li><li>fokusu;</li><li>treści, która zmienia sens strony internetowej.</li></ol><blockquote><p><strong>Uwaga</strong></p><p>Zmiana treści nie zawsze oznacza zmianę kontekstu. Zmiana w treści, na przykład rozwinięcie drzewa, dynamicznego menu lub zakładki niekoniecznie zmieniają kontekst, dopóki nie zmienią jednego z powyższych (np. fokusu).</p></blockquote><p><em>Przykład:</em> Otwarcie nowego okna, przeniesienie fokusu na inny obiekt, przejście na inną stronę internetową (włączając w to także każdą sytuację, kiedy użytkownikowi tylko wydaje się, że przechodzi na inną stronę internetową) lub znaczące przekształcenie wyglądu strony są przykładami zmiany kontekstu.</p>",
  "zobowiązanie prawne": "<p>transakcja, gdzie osoba wiąże się prawnym obowiązkiem lub korzyścią</p><p><em>Przykład:</em> akt ślubu, umowa handlowa (finansowa i prawna), testament, pożyczka, adopcja, zaciągnięcie się do armii, kontrakt dowolnego rodzaju itp.</p>",
  "zsynchronizowane media": "<p>audio lub wideo zsynchronizowane z innym formatem w celu prezentacji informacji lub interakcji z komponentami opartymi na czasie, o ile nie jest to wyraźnie oznaczona alternatywa dla tekstu</p>",
  "zwolnienie nacisku": "<p>zdarzenie dotykowe, które następuje potem, gdy bodziec wyzwalający wskaźnik zwalnia „wciśnięty” wcześniej punkt interaktywny</p><p>Zwolnienie nacisku może mieć różne nazwy na różnych platformach, takie jak „touchend” lub „mouseup”.\"</p>",
  "żargon": "<p>słowa używane w pewien specyficzny sposób w pewnych specyficzny środowiskach</p><p><em>Przykład:</em> Wyrażenie „lepkie klawisze” używane jest w żargonie środowisk zajmujących się technologiami wspomagającymi i technologiami dostępności</p>"
};
